window.ScripturaLexicons.BDAG_PART_0268 = {"source":"BDAG","searchAnchorId":"bdag-search-anchor","entryAnchorId":"bdag-entry-anchor","rowsHtml":"<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-bdag-0268-01\" data-source=\"BDAG\" data-search=\"παράβασις, εως, ἡ substantivo feminino transgressão; violação BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">παράβασις, εως, ἡ</td><td>substantivo feminino</td><td>transgressão; violação</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-bdag-0268-02\" data-source=\"BDAG\" data-search=\"παραβάτης, ου, ὁ substantivo masculino transgressor; violador BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">παραβάτης, ου, ὁ</td><td>substantivo masculino</td><td>transgressor; violador</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-bdag-0268-03\" data-source=\"BDAG\" data-search=\"παραβιάζομαι verbo médio depoente insistir; persuadir vigorosamente BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">παραβιάζομαι</td><td>verbo médio depoente</td><td>insistir; persuadir vigorosamente</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-bdag-0268-04\" data-source=\"BDAG\" data-search=\"παραβλέπω verbo negligenciar; desprezar BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">παραβλέπω</td><td>verbo</td><td>negligenciar; desprezar</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-bdag-0268-05\" data-source=\"BDAG\" data-search=\"παραβολεύομαι verbo médio arriscar; expor a perigo BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">παραβολεύομαι</td><td>verbo médio</td><td>arriscar; expor a perigo</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-bdag-0268-06\" data-source=\"BDAG\" data-search=\"παραβολή, ῆς, ἡ substantivo feminino parábola; figura; comparação BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">παραβολή, ῆς, ἡ</td><td>substantivo feminino</td><td>parábola; figura; comparação</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-bdag-0268-07\" data-source=\"BDAG\" data-search=\"παραβουλεύομαι verbo médio ser descuidado BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">παραβουλεύομαι</td><td>verbo médio</td><td>ser descuidado</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-bdag-0268-08\" data-source=\"BDAG\" data-search=\"παραβύω verbo cravar; introduzir BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">παραβύω</td><td>verbo</td><td>cravar; introduzir</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-bdag-0268-09\" data-source=\"BDAG\" data-search=\"παραγγελία, ας, ἡ substantivo feminino ordem; mandamento; exortação BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">παραγγελία, ας, ἡ</td><td>substantivo feminino</td><td>ordem; mandamento; exortação</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-bdag-0268-10\" data-source=\"BDAG\" data-search=\"παραγγέλλω verbo ordenar; instruir; proibir BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">παραγγέλλω</td><td>verbo</td><td>ordenar; instruir; proibir</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-bdag-0268-11\" data-source=\"BDAG\" data-search=\"παράγγελμα, ατος, τό substantivo neutro preceito; ordem BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">παράγγελμα, ατος, τό</td><td>substantivo neutro</td><td>preceito; ordem</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-bdag-0268-12\" data-source=\"BDAG\" data-search=\"παραγίνομαι verbo aproximar-se; chegar; comparecer BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">παραγίνομαι</td><td>verbo</td><td>aproximar-se; chegar; comparecer</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-bdag-0268-13\" data-source=\"BDAG\" data-search=\"παράγω verbo passar; introduzir; desaparecer BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">παράγω</td><td>verbo</td><td>passar; introduzir; desaparecer</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-bdag-0268-14\" data-source=\"BDAG\" data-search=\"παραδειγματίζω verbo expor à vergonha pública BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">παραδειγματίζω</td><td>verbo</td><td>expor à vergonha pública</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-bdag-0268-15\" data-source=\"BDAG\" data-search=\"παράδεισος, ου, ὁ substantivo masculino jardim do Éden; paraíso BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">παράδεισος, ου, ὁ</td><td>substantivo masculino</td><td>jardim do Éden; paraíso</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-bdag-0268-16\" data-source=\"BDAG\" data-search=\"παραδέχομαι verbo aceitar; acolher; receber BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">παραδέχομαι</td><td>verbo</td><td>aceitar; acolher; receber</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-bdag-0268-17\" data-source=\"BDAG\" data-search=\"παραδιατριβή, ῆς, ἡ substantivo feminino ocupação inútil BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">παραδιατριβή, ῆς, ἡ</td><td>substantivo feminino</td><td>ocupação inútil</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-bdag-0268-18\" data-source=\"BDAG\" data-search=\"παραδίδωμι verbo entregar; confiar; transmitir; permitir BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">παραδίδωμι</td><td>verbo</td><td>entregar; confiar; transmitir; permitir</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-bdag-0268-19\" data-source=\"BDAG\" data-search=\"παράδοξος, ον adjetivo maravilhoso; extraordinário BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">παράδοξος, ον</td><td>adjetivo</td><td>maravilhoso; extraordinário</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-bdag-0268-20\" data-source=\"BDAG\" data-search=\"παράδοσις, εως, ἡ substantivo feminino tradição; entrega BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">παράδοσις, εως, ἡ</td><td>substantivo feminino</td><td>tradição; entrega</td><td><span class=\"source-pill\">BDAG</span></td></tr>","cardsHtml":"<article class=\"entry-card\" id=\"entry-bdag-0268-01\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">παράβασις, εως, ἡ</h1><div class=\"entry-meta\"><span>substantivo feminino</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução integral</div><p class=\"entry-text\"><span class=\"greek\">παράβασις</span>, <span class=\"greek\">εως</span>, <span class=\"greek\">ἡ</span> (<span class=\"greek\">παραβαίνω</span>; ver verbete seguinte; Strabo e outros; papiros, LXX, En, Test12Patr, GrBar; ApcEsdr 2:12 p. 26, 6 Tdf.; ApcMos, Philo, Joseph., Just.; Tat. 7:3), ato de desviar-se de um limite ou norma estabelecida, ultrapassagem, transgressão. Com genitivo objetivo (Plut., Mor. 122d, Ages. et Pomp. 662 [1, 5]; 2 Macc 15:10): <span class=\"greek\">ἡ</span> <span class=\"greek\">π</span>. <span class=\"greek\">τοῦ</span> <span class=\"greek\">νόμου</span>, «A violação da lei» (Porphyr., Abst. 2, 61 Nauck <span class=\"greek\">ἡ</span> <span class=\"greek\">τοῦ</span> <span class=\"greek\">νόμου</span> <span class=\"greek\">παράβασις</span>; Alex. Aphr., An. Mant. II 1 p. 158, 37 <span class=\"greek\">δικαίων</span> <span class=\"greek\">π</span>. = «violação das leis».—Philo, Somn. 2, 123; Jos., Ant. 8, 129 <span class=\"greek\">τ</span>. <span class=\"greek\">νομίμων</span> <span class=\"greek\">π</span>.; 13, 69 <span class=\"greek\">ἡ</span> <span class=\"greek\">τ</span>. <span class=\"greek\">νόμου</span> <span class=\"greek\">π</span>.; 18, 263; 340), <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ROM.2.23\" target=\"_blank\" rel=\"noopener noreferrer\">Ro 2:23</a>. Com genitivo subjetivo (Wsd 14:31): <span class=\"greek\">ἡ</span> <span class=\"greek\">π</span>. <span class=\"greek\">Ἀδάμ</span>, «A transgressão de Adão», 5:14. <span class=\"greek\">ἡ</span> <span class=\"greek\">π</span>. <span class=\"greek\">αὐτῶν</span>, B 12:5b. No plural: <span class=\"greek\">αἱ</span> <span class=\"greek\">π</span>. <span class=\"greek\">τοῦ</span> <span class=\"greek\">οἴκου</span> <span class=\"greek\">σου</span>, «As transgressões de tua família», Hv 2, 3, 1. Em uso absoluto (Plut., Mor. 209a; 746c; Ps 100:3; 4 Km 2:24, variante textual; En 98:5.—Sobre a queda de Adão no pecado: Iren. 4, 40, 3 [Harv. II 303, 6]; Orig., C. Cels. 4, 40, 23; <span class=\"greek\">ὁ</span> <span class=\"greek\">ἄνθρωπος</span> <span class=\"greek\">πρὸ</span> <span class=\"greek\">παραβάσεως</span>, Did., Gen. 82, 8), <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ROM.4.15\" target=\"_blank\" rel=\"noopener noreferrer\">Ro 4:15</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/HEB.9.15\" target=\"_blank\" rel=\"noopener noreferrer\">Hb 9:15</a>; B 12:5a. Com <span class=\"greek\">παρακοή</span>, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/HEB.2.2\" target=\"_blank\" rel=\"noopener noreferrer\">Hb 2:2</a>. Entre muitos outros vícios num catálogo de vícios, B 20:1. <span class=\"greek\">ἐν</span> <span class=\"greek\">π</span>. <span class=\"greek\">γίνεσθαι</span>, «Tornar-se transgressor», <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1TI.2.14\" target=\"_blank\" rel=\"noopener noreferrer\">1 Ti 2:14</a>. <span class=\"greek\">τῶν</span> <span class=\"greek\">παραβάσεων</span> <span class=\"greek\">χάριν</span>, «Por causa das transgressões», isto é, para torná-las possíveis e numerosas, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/GAL.3.19\" target=\"_blank\" rel=\"noopener noreferrer\">Gal 3:19</a>.—DELG s.v. <span class=\"greek\">βαίνω</span>. M-M. EDNT. TW.</p></section></article>\n<article class=\"entry-card\" id=\"entry-bdag-0268-02\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">παραβάτης, ου, ὁ</h1><div class=\"entry-meta\"><span>substantivo masculino</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução integral</div><p class=\"entry-text\"><span class=\"greek\">παραβάτης</span>, <span class=\"greek\">ου</span>, <span class=\"greek\">ὁ</span> (<span class=\"greek\">παραβαίνω</span>; ver verbete anterior; nos escritos não bíblicos, sobretudo um guerreiro ao lado do auriga ou certo tipo de soldado de infantaria), em nossa literatura apenas violador, transgressor (assim Aeschyl., Eum. 553 [sobre a leitura <span class=\"greek\">παρβάδαν</span>, ver Schwyzer II 492]; Pythag., Ep. 3, 7 <span class=\"greek\">παραβάται</span> <span class=\"greek\">τᾶν</span> <span class=\"greek\">ὁμολογιᾶν</span> <span class=\"greek\">γινόμεθα</span>; Polemo [Macrobius, Saturnalia 5, 19, 29] <span class=\"greek\">π</span>. <span class=\"greek\">θεῶν</span>; talvez PMich 478, 16 [II d.C.]; Suda sobre <span class=\"greek\">Ἀμάχιος</span>; Sym.; <span class=\"greek\">π</span>. <span class=\"greek\">τῆς</span> <span class=\"greek\">τοῦ</span> <span class=\"greek\">θεοῦ</span> <span class=\"greek\">ἐντολῆς</span>, Did., Gen. 84, 27; Theoph. Ant. 2, 16 [p. 140, 13]): (<span class=\"greek\">τοῦ</span>) <span class=\"greek\">νόμου</span>, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ROM.2.25\" target=\"_blank\" rel=\"noopener noreferrer\">Ro 2:25</a>, 27; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/JAS.2.11\" target=\"_blank\" rel=\"noopener noreferrer\">Js 2:11</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.6.4\" target=\"_blank\" rel=\"noopener noreferrer\">Lk 6:4</a> D. Em uso absoluto, pecador (Ps.-Clem., Hom. 3, 39), <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/GAL.2.18\" target=\"_blank\" rel=\"noopener noreferrer\">Gal 2:18</a> (WMundle, ZNW 23, 1924, 152f); <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/JAS.2.9\" target=\"_blank\" rel=\"noopener noreferrer\">Js 2:9</a>.—DELG s.v. <span class=\"greek\">βαίνω</span>. M-M. TW.</p></section></article>\n<article class=\"entry-card\" id=\"entry-bdag-0268-03\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">παραβιάζομαι</h1><div class=\"entry-meta\"><span>verbo médio depoente</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução integral</div><p class=\"entry-text\"><span class=\"greek\">παραβιάζομαι</span>, depoente médio, futuro ático, 3.ª pessoa do plural <span class=\"greek\">παραβιῶνται</span>, Am 6:10; 1.º aoristo <span class=\"greek\">παρεβιασάμην</span> (Epicurea p. 36, 5 Us.; Polyb., Plut. e outros; LXX; TestSol 26:4; ver Anz 359f). Do sentido de «empregar força» para realizar alguma coisa (Polyb. 24, 8, 3; Philo, Congr. Erud. Grat. 125; Jos., C. Ap. 2, 233), com acusativo («exercer violência contra», Plut., Mor. 19f <span class=\"greek\">μύθους</span>, Cleom. 16, 2 <span class=\"greek\">τ</span>. <span class=\"greek\">Ἀχαιούς</span>; Gen 19:9; cf. Dt 1:43), desenvolve-se o sentido de insistir vigorosamente, persuadir insistentemente, prevalecer sobre alguém (4 Km 2:17 e outros), <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.24.29\" target=\"_blank\" rel=\"noopener noreferrer\">Lk 24:29</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.16.15\" target=\"_blank\" rel=\"noopener noreferrer\">Ac 16:15</a> (cf. 1 Km 28:23). Seguido de acusativo e infinitivo: <span class=\"greek\">ὁ</span> <span class=\"greek\">παραβιασάμενος</span> <span class=\"greek\">ἑαυτόν</span> <span class=\"greek\">τε</span> <span class=\"greek\">καί</span> <span class=\"greek\">τινας</span> <span class=\"greek\">προσελθεῖν</span> <span class=\"greek\">ἑκοντάς</span>, «Aquele que persuadiu a si mesmo e a outros a apresentarem-se voluntariamente», MPol 4.—DELG s.v. <span class=\"greek\">βία</span>. M-M.</p></section></article>\n<article class=\"entry-card\" id=\"entry-bdag-0268-04\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">παραβλέπω</h1><div class=\"entry-meta\"><span>verbo</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução integral</div><p class=\"entry-text\"><span class=\"greek\">παραβλέπω</span> (Aristoph. e outros; LXX; TestSol 22:5; ApcSed 16:1 [imperfeito <span class=\"greek\">ἐπαράβλεπον</span>]; Philo, Virt. 173), olhar para o lado para não ver, deixar de observar, negligenciar, desprezar (Polyb. 6, 46, 6 <span class=\"greek\">τὰς</span> <span class=\"greek\">διαφοράς</span>; Sir 38:9), com <span class=\"greek\">τινά</span>, alguém; a respeito dos necessitados, das viúvas e dos órfãos, Hs 1:8.</p></section></article>\n<article class=\"entry-card\" id=\"entry-bdag-0268-05\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">παραβολεύομαι</h1><div class=\"entry-meta\"><span>verbo médio</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução integral</div><p class=\"entry-text\"><span class=\"greek\">παραβολεύομαι</span> (Sb 7562 [II d.C.]; = emprego passivo de <span class=\"greek\">παραβάλλω</span> em Thu. e outros), 1.º aoristo <span class=\"greek\">παρεβολευσάμην</span>, expor a perigo, arriscar (IPontEux I2, 39, 26–28 [= IGR I/II, 856] <span class=\"greek\">ἀλλὰ</span> <span class=\"greek\">καὶ</span> [<span class=\"greek\">μέχρι</span>] <span class=\"greek\">περάτων</span> <span class=\"greek\">γῆς</span> <span class=\"greek\">ἐμαρτυρήθη</span> <span class=\"greek\">τοὺς</span> <span class=\"greek\">ὑπὲρ</span> <span class=\"greek\">φιλίας</span> <span class=\"greek\">κινδύνους</span> <span class=\"greek\">μέχρι</span> <span class=\"greek\">Σεβαστῶν</span> <span class=\"greek\">συμμαχίᾳ</span> <span class=\"greek\">παραβολευσάμενος</span> = «Mas também até os confins da terra se testemunhou que, em benefício da amizade, ele se expôs aos perigos ao auxiliar em contendas [jurídicas], levando [as causas de seus clientes] até mesmo perante os imperadores». Dssm., LO 69 [LAE 84]), com <span class=\"greek\">τινί</span>, alguma coisa (sobre o dativo, ver Mlt. 64 e cf. <span class=\"greek\">παραβάλλεσθαι</span> <span class=\"greek\">τοῖς</span> <span class=\"greek\">ὅλοις</span>, «Arriscar tudo», Polyb. 2, 26, 3; 3, 94, 4): <span class=\"greek\">τῇ</span> <span class=\"greek\">ψυχῇ</span>, «A própria vida» (cf. Diod S 3, 36, 4 <span class=\"greek\">ταῖς</span> <span class=\"greek\">ψυχαῖς</span> <span class=\"greek\">παραβάλλεσθαι</span>; SIG 762, 39 <span class=\"greek\">ψυχῇ</span> <span class=\"greek\">καὶ</span> <span class=\"greek\">σώματι</span> <span class=\"greek\">παραβαλλόμενος</span>), <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/PHP.2.30\" target=\"_blank\" rel=\"noopener noreferrer\">Phil 2:30</a>.—DELG s.v. <span class=\"greek\">βάλλω</span>. M-M.</p></section></article>\n<article class=\"entry-card\" id=\"entry-bdag-0268-06\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">παραβολή, ῆς, ἡ</h1><div class=\"entry-meta\"><span>substantivo feminino</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução integral</div><p class=\"entry-text\"><span class=\"greek\">παραβολή</span>, <span class=\"greek\">ῆς</span>, <span class=\"greek\">ἡ</span> (<span class=\"greek\">παραβάλλω</span>; Pla., Isocr. e posteriores; inscrições, papiros, LXX; En; TestSol 20:4; Just.; Mel., P.—JWackernagel, Parabola: IndogF 31, 1912/13, 262–67).<br>\n① Aquilo que serve de modelo ou exemplo que aponta para além de si mesmo, visando a uma realização posterior, tipo, figura: <span class=\"greek\">παραβολὴ</span> <span class=\"greek\">εἰς</span> <span class=\"greek\">τὸν</span> <span class=\"greek\">καιρὸν</span> <span class=\"greek\">τὸν</span> <span class=\"greek\">ἐνεστηκότα</span>, «Símbolo (que aponta) para a época presente», <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/HEB.9.9\" target=\"_blank\" rel=\"noopener noreferrer\">Hb 9:9</a>. <span class=\"greek\">ἐν</span> <span class=\"greek\">παραβολῇ</span>, «Como um tipo» (da morte violenta e da ressurreição de Cristo), 11:19. <span class=\"greek\">λέγει</span> <span class=\"greek\">ὁ</span> <span class=\"greek\">προφήτης</span> <span class=\"greek\">παραβολὴν</span> <span class=\"greek\">κυρίου</span>, B 6:10, passagem em que o significado pode ser «O profeta pronuncia uma parábola do Senhor» (Goodsp.), ou «O profeta fala do Senhor em linguagem figurada» (Kleist), ou ainda «O profeta fala na linguagem figurada que lhe foi dada pelo Senhor». Com <span class=\"greek\">αἴνιγμα</span>, PtK 4 p. 15, 31. As coisas presentes ou futuras não podem ser compreendidas pelo cristão comum <span class=\"greek\">διὰ</span> <span class=\"greek\">τὸ</span> <span class=\"greek\">ἐν</span> <span class=\"greek\">παραβολαῖς</span> <span class=\"greek\">κεῖσθαι</span>, «Porque estão expressas em figuras», B 17:2.<br>\n② Narrativa ou dito de extensão variável, destinado a ilustrar uma verdade sobretudo por meio de comparação ou símile, comparação, ilustração, parábola, provérbio, máxima.<br>\nⓐ Nos Evangelhos Sinóticos, a palavra designa várias formas de ilustração utilizadas nos ensinamentos de Jesus (17 vezes em Mt, 13 em Mk, 18 em Lk; cf. Euclides [400 a.C.], que, segundo Diog. L. 2, 107, rejeitava <span class=\"greek\">ὁ</span> <span class=\"greek\">διὰ</span> <span class=\"greek\">παραβολῆς</span> <span class=\"greek\">λόγος</span>; Aristot., Rhet. 2, 20, 2ff; <span class=\"greek\">Περὶ</span> <span class=\"greek\">ὕψους</span> 37; Vi. Aesopi II p. 307, 15 Eb.; Biogr. p. 87 <span class=\"greek\">Ὁμήρου</span> <span class=\"greek\">παραβολαί</span>; Philo, Conf. Lingu. 99; Jos., Ant. 8, 44. O AT grego também emprega <span class=\"greek\">παραβολή</span> para diversas palavras e expressões que envolvem comparação, incluindo enigmas [ver Jülicher abaixo: I2 32–40].—En 1:2; 3. Cf. <span class=\"greek\">π</span>. <span class=\"greek\">κυριακαί</span>, Iren. 1, 8, 1 [Harv I 67, 1]). Sobre a provável influência do AT no emprego da comparação em narrativas, ver Ezk 17. <span class=\"greek\">λέγειν</span>, <span class=\"greek\">εἰπεῖν</span> <span class=\"greek\">παραβολήν</span>: <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.13.6\" target=\"_blank\" rel=\"noopener noreferrer\">Lk 13:6</a>; 16:19 D; 19:11 (início da mais longa «parábola» dos Sinóticos: 17 versículos). <span class=\"greek\">τινί</span>, «A alguém», 4:23 (a «parábola» mais breve: 3 palavras; aqui e na passagem seguinte <span class=\"greek\">π</span>. = «provérbio», citado por Jesus); 6:39; 18:1; 21:29. <span class=\"greek\">πρός</span> <span class=\"greek\">τινα</span>, «A alguém», 5:36; 12:16, 41; 14:7; 15:3; 18:9; 20:9; com referência a alguém, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MRK.12.12\" target=\"_blank\" rel=\"noopener noreferrer\">Mk 12:12</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.20.19\" target=\"_blank\" rel=\"noopener noreferrer\">Lk 20:19</a>. <span class=\"greek\">παραβολὴν</span> <span class=\"greek\">λαλεῖν</span> <span class=\"greek\">τινι</span>, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.13.33\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 13:33</a>. <span class=\"greek\">παραβολὴν</span> <span class=\"greek\">παρατιθέναι</span> <span class=\"greek\">τινί</span>, «Apresentar uma parábola a alguém», vv. 24, 31. <span class=\"greek\">τελεῖν</span> <span class=\"greek\">τὰς</span> <span class=\"greek\">παραβολάς</span>, «Concluir as parábolas», v. 53. <span class=\"greek\">διασαφεῖν</span> (variante textual <span class=\"greek\">φράζειν</span>) <span class=\"greek\">τινι</span> <span class=\"greek\">τὴν</span> <span class=\"greek\">παραβολήν</span>, v. 36. <span class=\"greek\">φράζειν</span> <span class=\"greek\">τινὶ</span> <span class=\"greek\">τὴν</span> <span class=\"greek\">παρ</span>., «Explicar a parábola», 15:15. <span class=\"greek\">ἀκούειν</span>, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.13.18\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 13:18</a>; 21:33, 45. <span class=\"greek\">γνῶναι</span> e <span class=\"greek\">εἰδέναι</span>, «Compreender», <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MRK.4.13\" target=\"_blank\" rel=\"noopener noreferrer\">Mk 4:13b</a> e outros. <span class=\"greek\">μαθεῖν</span> <span class=\"greek\">τὴν</span> <span class=\"greek\">παρ</span>. <span class=\"greek\">ἀπό</span> <span class=\"greek\">τινος</span>, «Aprender a parábola a partir de alguma coisa», <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.24.32\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 24:32</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MRK.13.28\" target=\"_blank\" rel=\"noopener noreferrer\">Mk 13:28</a>. (<span class=\"greek\">ἐπ</span>)<span class=\"greek\">ἐρωτᾶν</span> <span class=\"greek\">τινα</span> <span class=\"greek\">τὴν</span> <span class=\"greek\">παρ</span>., «Perguntar a alguém o significado da parábola», <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MRK.7.17\" target=\"_blank\" rel=\"noopener noreferrer\">Mk 7:17</a> (referindo-se ao v. 15); cf. 4:10. Também <span class=\"greek\">ἐπερωτᾶν</span> <span class=\"greek\">τινα</span> <span class=\"greek\">περὶ</span> <span class=\"greek\">τῆς</span> <span class=\"greek\">παρ</span>., 7:17, variante textual; <span class=\"greek\">ἐπηρώτων</span> <span class=\"greek\">αὐτὸν</span> <span class=\"greek\">τίς</span> <span class=\"greek\">εἴη</span> <span class=\"greek\">ἡ</span> <span class=\"greek\">παρ</span>., «Perguntavam-lhe qual era o significado da parábola», <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.8.9\" target=\"_blank\" rel=\"noopener noreferrer\">Lk 8:9</a>; a resposta: <span class=\"greek\">ἔστιν</span> <span class=\"greek\">δὲ</span> <span class=\"greek\">αὕτη</span> <span class=\"greek\">ἡ</span> <span class=\"greek\">παρ</span>., «Mas o significado da parábola é este», v. 11.—<span class=\"greek\">παραβολαῖς</span> <span class=\"greek\">λαλεῖν</span> <span class=\"greek\">τινί</span> <span class=\"greek\">τι</span>, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MRK.4.33\" target=\"_blank\" rel=\"noopener noreferrer\">Mk 4:33</a>. Com genitivo daquilo que constitui o assunto da parábola: <span class=\"greek\">ἡ</span> <span class=\"greek\">παρ</span>. <span class=\"greek\">τοῦ</span> <span class=\"greek\">σπείραντος</span>, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.13.18\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 13:18</a>. <span class=\"greek\">τῶν</span> <span class=\"greek\">ζιζανίων</span>, v. 36 (cf. <span class=\"greek\">ἡ</span> <span class=\"greek\">περὶ</span> <span class=\"greek\">τοῦ</span> … <span class=\"greek\">τελώνου</span> <span class=\"greek\">παρ</span>., Orig., C. Cels. 3, 64, 11).—Com preposição: <span class=\"greek\">εἶπεν</span> <span class=\"greek\">διὰ</span> <span class=\"greek\">παραβολῆς</span>, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.8.4\" target=\"_blank\" rel=\"noopener noreferrer\">Lk 8:4</a> (Orig., C. Cels. 1, 5, 11).—<span class=\"greek\">χωρὶς</span> <span class=\"greek\">παραβολῆς</span> <span class=\"greek\">οὐδὲν</span> <span class=\"greek\">ἐλάλει</span> <span class=\"greek\">αὐτοῖς</span>, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.13.34\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 13:34b</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MRK.4.34\" target=\"_blank\" rel=\"noopener noreferrer\">Mk 4:34</a>.—Sobretudo com <span class=\"greek\">ἐν</span>: <span class=\"greek\">τιθέναι</span> <span class=\"greek\">τὴν</span> <span class=\"greek\">βασιλείαν</span> <span class=\"greek\">τοῦ</span> <span class=\"greek\">θεοῦ</span> <span class=\"greek\">ἐν</span> <span class=\"greek\">παραβολῇ</span>, «Apresentar o Reino de Deus numa parábola», v. 30. <span class=\"greek\">ἐν</span> <span class=\"greek\">παραβολαῖς</span> <span class=\"greek\">λαλεῖν</span> <span class=\"greek\">τινι</span>, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.13.10\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 13:10</a>, 13; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MRK.12.1\" target=\"_blank\" rel=\"noopener noreferrer\">Mk 12:1</a>. <span class=\"greek\">ἐν</span> <span class=\"greek\">παραβολαῖς</span> <span class=\"greek\">λέγειν</span> <span class=\"greek\">τινί</span>, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.22.1\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 22:1</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MRK.3.23\" target=\"_blank\" rel=\"noopener noreferrer\">Mk 3:23</a>. <span class=\"greek\">λαλεῖν</span> <span class=\"greek\">τινί</span> <span class=\"greek\">τι</span> <span class=\"greek\">ἐν</span> <span class=\"greek\">παραβολαῖς</span>, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.13.3\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 13:3</a>, 34a. <span class=\"greek\">διδάσκειν</span> <span class=\"greek\">τινά</span> <span class=\"greek\">τι</span> <span class=\"greek\">ἐν</span> <span class=\"greek\">παραβολαῖς</span>, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MRK.4.2\" target=\"_blank\" rel=\"noopener noreferrer\">Mk 4:2</a>. <span class=\"greek\">ἀνοίξω</span> <span class=\"greek\">ἐν</span> <span class=\"greek\">παραβολαῖς</span> <span class=\"greek\">τὸ</span> <span class=\"greek\">στόμα</span> <span class=\"greek\">μου</span>, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.13.35\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 13:35</a> (Ps 77:2). <span class=\"greek\">γίνεταί</span> <span class=\"greek\">τινί</span> <span class=\"greek\">τι</span> <span class=\"greek\">ἐν</span> <span class=\"greek\">παραβολαῖς</span>, «Algo chega a alguém em forma de parábolas», <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MRK.4.11\" target=\"_blank\" rel=\"noopener noreferrer\">Mk 4:11</a>; cf. <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.8.10\" target=\"_blank\" rel=\"noopener noreferrer\">Lk 8:10</a>. Segundo Eus. (3, 39, 11), Pápias apresentou algumas parábolas incomuns do Salvador, isto é, atribuídas a Jesus: Papias (2:11).—AJülicher, Die Gleichnisreden Jesu I2 1899; II 1899 [bibliografia antiga em I 203–322]; GHeinrici, RE VI 688–703, XXIII 561f; CBugge, Die Hauptparabeln Jesu 1903; PFiebig, Altjüdische Gleichnisse und d. Gleichnisse Jesu 1904, D. Gleichnisse Jesu im Lichte der rabb. Gleich. 1912, D. Erzählungsstil der Ev. 1925; LFonck, Die Parabeln des Herrn3 1909 (com ampla bibliografia sobre cada parábola), The Parables of the Gospel3 1918; JKögel, BFCT XIX 6, 1915; MMeinertz, Die Gleichnisse Jesu 1916; 4.ª edição ’48; HWeinel, Die Gleichnisse Jesu5 1929; RBultmann, D. Geschichte der synoptischen Tradition2 ’31, 179–222; MDibelius, D. Formgeschichte des Ev.2 33; EBuonaiuti, Le parabole di Gesù: Religio 10–13, ’34–37; WOesterly, The Gospel Parables in the Light of Their Jewish Background ’36; EWechssler, Hellas im Ev. ’36, 267–85; CDodd, The Parables of the Kgdm.3 ’36; BSmith, The Par. of the Syn. Gosp. ’37; WMichaelis, Es ging e. Sämann aus. zu säen ’38; OPiper, The Understanding of the Syn. Par.: EvQ 14, ’42, 42–53; CMasson, Les Paraboles de Marc IV ’45; JJeremias, D. Gleichn. Jesu4 ’56 (tradução inglesa ’55); ELinnemann, Jesus of the Parables, tradução de JSturdy, ’66; AWeiser, D. Knechtsgleichnisse der synopt. Evv. ’71; JKingsbury, The Parables of Jesus in Mt 13, ’69; FDanker, Fresh Persp. on Mt, CTM 41, ’70, 478–90; JKingsbury, ibid. 42, ’71, 579–96; TManson, The Teaching of Jesus, ’55, 57–86; JSider, Biblica 62, ’81, 453–70 (sinóticos); ECuvillier, Le concept de <span class=\"greek\">ΠΑΡΑΒΟΛΗ</span> dans le second évangile ’93.<br>\nⓑ À parte os Evangelhos Sinóticos, <span class=\"greek\">παρ</span>. ocorre frequentemente em nossa literatura em Hermas (como título: Hs 1:1; 2:1; 3:1; 4:1; 5:1; [6:1; 7:1; 8:1]), mas não independentemente da tradição sinótica. Hermas emprega <span class=\"greek\">παρ</span>. apenas uma vez para designar uma verdadeira parábola ilustrativa (dupla), em Hm 11:18. Nas demais ocorrências, <span class=\"greek\">παρ</span>. designa em Hermas uma apresentação enigmática, ora vista em visão, ora expressa em palavras, mas sempre necessitada de interpretação detalhada: com genitivo de conteúdo (ver a acima), <span class=\"greek\">τοῦ</span> <span class=\"greek\">πύργου</span>, «Sobre a torre», Hv 3, 3, 2. <span class=\"greek\">τοῦ</span> <span class=\"greek\">ἀγροῦ</span>, «Sobre o campo», Hs 5, 4, 1. <span class=\"greek\">τῶν</span> <span class=\"greek\">ὀρέων</span>, 9, 29, 4. <span class=\"greek\">δηλοῦν</span> <span class=\"greek\">τὴν</span> <span class=\"greek\">παραβολήν</span>, 5, 4, 1a. <span class=\"greek\">παρ</span>. <span class=\"greek\">ἐστιν</span> <span class=\"greek\">ταῦτα</span>, 5, 4, 1b. <span class=\"greek\">ἀκούειν</span> <span class=\"greek\">τὴν</span> <span class=\"greek\">παραβολήν</span>, Hv 3, 3, 2; 3, 12, 1; Hs 5, 2, 1. <span class=\"greek\">παραβολὰς</span> <span class=\"greek\">λαλεῖν</span> <span class=\"greek\">τινι</span>, 5, 4, 2a. <span class=\"greek\">τὰ</span> <span class=\"greek\">ῥήματα</span> <span class=\"greek\">τὰ</span> <span class=\"greek\">λεγόμενα</span> <span class=\"greek\">διὰ</span> <span class=\"greek\">παραβολῶν</span>, 5, 4, 3b; <span class=\"greek\">γράφειν</span> <span class=\"greek\">τὰς</span> <span class=\"greek\">παρ</span>., Hv 5:5f; Hs 9, 1, 1; <span class=\"greek\">συνιέναι</span> <span class=\"greek\">τὰς</span> <span class=\"greek\">παρ</span>., Hm 10, 1, 3. <span class=\"greek\">γινώσκειν</span>, Hs 5, 3, 1a; 9, 5, 5. <span class=\"greek\">νοεῖν</span>, Hm 10, 1, 4; Hs 5, 3, 1b. <span class=\"greek\">ἐπιλύειν</span> <span class=\"greek\">τινὶ</span> <span class=\"greek\">παρ</span>., 5, 3, 1c; 5, 4, 2b; 3a. <span class=\"greek\">συντελεῖν</span>, 9, 29, 4. <span class=\"greek\">ἡ</span> <span class=\"greek\">ἐπίλυσις</span> <span class=\"greek\">τῆς</span> <span class=\"greek\">παρ</span>., «Explicação, interpretação da parábola», 5, 6, 8; <span class=\"greek\">αἱ</span> <span class=\"greek\">ἐπιλύσεις</span> <span class=\"greek\">τῶν</span> <span class=\"greek\">παρ</span>., 5, 5, 1. <span class=\"greek\">ὁ</span> <span class=\"greek\">υἱὸς</span> <span class=\"greek\">τοῦ</span> <span class=\"greek\">θεοῦ</span> <span class=\"greek\">εἰς</span> <span class=\"greek\">δούλου</span> <span class=\"greek\">τρόπον</span> <span class=\"greek\">κεῖται</span> <span class=\"greek\">ἐν</span> <span class=\"greek\">τῇ</span> <span class=\"greek\">παρ</span>., «O Filho de Deus aparece na parábola na condição de servo», 5, 5, 5. <span class=\"greek\">ἡ</span> <span class=\"greek\">παρ</span>. <span class=\"greek\">εἰς</span> <span class=\"greek\">τοὺς</span> <span class=\"greek\">δούλους</span> <span class=\"greek\">τοῦ</span> <span class=\"greek\">θεοῦ</span> <span class=\"greek\">κεῖται</span>, «A parábola refere-se aos servos de Deus», 2:4.—Ver também os títulos das diversas partes da terceira seção de Hermas (as Parábolas) e, sobre Hermas em geral, ver Jülicher, op. cit. I 204–209.—<span class=\"greek\">εἰ</span> <span class=\"greek\">δὲ</span> <span class=\"greek\">δεῖ</span> <span class=\"greek\">ἡμᾶς</span> <span class=\"greek\">καὶ</span> <span class=\"greek\">ἀπὸ</span> <span class=\"greek\">τῶν</span> <span class=\"greek\">σπερμάτων</span> <span class=\"greek\">μὴ</span> <span class=\"greek\">ποιεῖσθαι</span> <span class=\"greek\">τὴν</span> <span class=\"greek\">παρ</span>., «Mas se não devemos extrair nossa comparação das (ações das) sementes», AcPlCor 2:28.—BScott, Profiles of Jesus, Parables: The Fourth R 10, ’97, 3–14.—B. 1262. DELG s.v. <span class=\"greek\">βάλλω</span>. M-M. EDNT. TW. Sv.</p></section></article>\n<article class=\"entry-card\" id=\"entry-bdag-0268-07\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">παραβουλεύομαι</h1><div class=\"entry-meta\"><span>verbo médio</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução integral</div><p class=\"entry-text\"><span class=\"greek\">παραβουλεύομαι</span>, 1.º aoristo <span class=\"greek\">παρεβουλευσάμην</span> (Cat. Cod. Astr. XII 188, 27; Hesych., provavelmente com referência a <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/PHP.2.30\" target=\"_blank\" rel=\"noopener noreferrer\">Phil 2:30</a>), ser descuidado, com <span class=\"greek\">τινί</span>, em relação a alguma coisa: <span class=\"greek\">τῇ</span> <span class=\"greek\">ψυχῇ</span>, «Não ter cuidado com a própria vida», <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/PHP.2.30\" target=\"_blank\" rel=\"noopener noreferrer\">Phil 2:30</a>, variante textual (em lugar de <span class=\"greek\">παραβολ</span>., ver este verbete).—DELG s.v. <span class=\"greek\">βούλομαι</span>.</p></section></article>\n<article class=\"entry-card\" id=\"entry-bdag-0268-08\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">παραβύω</h1><div class=\"entry-meta\"><span>verbo</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução integral</div><p class=\"entry-text\"><span class=\"greek\">παραβύω</span> (<span class=\"greek\">βύω</span>, «introduzir à força, encher»), 1.º aoristo <span class=\"greek\">παρέβυσα</span> (Hippocr. e outros), introduzir, cravar em: <span class=\"greek\">π</span>. <span class=\"greek\">ξιφίδιον</span>, «Cravar um punhal (num corpo)», MPol 16:1 (Lucian, Toxar. 58 <span class=\"greek\">παραβύειν</span> <span class=\"greek\">ἐς</span> <span class=\"greek\">τὴν</span> <span class=\"greek\">πλευρὰν</span> <span class=\"greek\">τὸν</span> <span class=\"greek\">ἀκινάκην</span>).—DELG s.v. <span class=\"greek\">βυνέω</span>.</p></section></article>\n<article class=\"entry-card\" id=\"entry-bdag-0268-09\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">παραγγελία, ας, ἡ</h1><div class=\"entry-meta\"><span>substantivo feminino</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução integral</div><p class=\"entry-text\"><span class=\"greek\">παραγγελία</span>, <span class=\"greek\">ας</span>, <span class=\"greek\">ἡ</span> (<span class=\"greek\">παραγγέλλω</span>; X. e outros; Diod S 4, 12, 3; papiros, Philo, In Flacc. 141; Jos., Ant. 16, 241), anúncio referente a algo que precisa ser feito, ordem, mandamento, preceito, conselho, exortação: <span class=\"greek\">παραγγελίαν</span> <span class=\"greek\">λαμβάνειν</span>, «Receber uma ordem», <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.16.24\" target=\"_blank\" rel=\"noopener noreferrer\">Ac 16:24</a>; 1 Cl 42:3. <span class=\"greek\">παραγγελίᾳ</span> <span class=\"greek\">παραγγέλλειν</span> <span class=\"greek\">τινί</span> (B-D-F §198, 6; Rdm.2 128; Rob. 531), seguido de <span class=\"greek\">μή</span> e infinitivo, «Dar ordens rigorosas a alguém», <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.5.28\" target=\"_blank\" rel=\"noopener noreferrer\">Ac 5:28</a>. Sobre instruções apostólicas: <span class=\"greek\">παραγγελίας</span> <span class=\"greek\">διδόναι</span> <span class=\"greek\">τινί</span>, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1TH.4.2\" target=\"_blank\" rel=\"noopener noreferrer\">1 Th 4:2</a>; <span class=\"greek\">παρατίθεσθαί</span> <span class=\"greek\">τινι</span>, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1TI.1.18\" target=\"_blank\" rel=\"noopener noreferrer\">1 Ti 1:18</a>; cf. v. 5.—GMilligan, St. Paul’s Epistles to the Thess. 1908, 47.—DELG s.v. <span class=\"greek\">ἄγγελος</span>. M-M. TW. Spicq.</p></section></article>\n<article class=\"entry-card\" id=\"entry-bdag-0268-10\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">παραγγέλλω</h1><div class=\"entry-meta\"><span>verbo</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução integral</div><p class=\"entry-text\"><span class=\"greek\">παραγγέλλω</span> (<span class=\"greek\">παρά</span>, <span class=\"greek\">ἀγγέλλω</span>), imperfeito <span class=\"greek\">παρήγγελλον</span>; 1.º aoristo <span class=\"greek\">παρήγγειλα</span>. Passiva: particípio perfeito <span class=\"greek\">παρηγγελμένος</span>, 3 Macc 4:14 (Aeschyl., Hdt. e posteriores; inscrições, papiros, LXX; TestSol 26:4 B; Test12Patr; ApcSed 9:5; ApcEsdr 4:28 p. 29, 2 Tdf.; Philo, Joseph., Just.), fazer um anúncio sobre algo que deve ser realizado, dar ordens, ordenar, instruir, determinar; empregado a respeito de diversas pessoas investidas de autoridade, governantes seculares, Jesus e os apóstolos. Em uso absoluto: <span class=\"greek\">παραγγέλλων</span>, «Ao dar minhas instruções», <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1CO.11.17\" target=\"_blank\" rel=\"noopener noreferrer\">1 Cor 11:17</a>. Seguido de infinitivo presente, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.15.5\" target=\"_blank\" rel=\"noopener noreferrer\">Ac 15:5</a>; seguido de acusativo e infinitivo aoristo, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1TI.6.13\" target=\"_blank\" rel=\"noopener noreferrer\">1 Ti 6:13f</a>, variante textual. <span class=\"greek\">τὶ</span>, «Determinar, exortar, insistir em» (Philo, Spec. Leg. 3, 80), <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/2TH.3.4\" target=\"_blank\" rel=\"noopener noreferrer\">2 Th 3:4</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1TI.4.11\" target=\"_blank\" rel=\"noopener noreferrer\">1 Ti 4:11</a>; 5:7. <span class=\"greek\">τινί</span> (Jos., Ant. 2, 311), «Exortar»: <span class=\"greek\">παραγγείλαντες</span> <span class=\"greek\">αὐτοῖς</span>, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.15.5\" target=\"_blank\" rel=\"noopener noreferrer\">Ac 15:5</a>, variante textual; «Determinar, dar ordens a alguém»: <span class=\"greek\">καθὼς</span> <span class=\"greek\">ὑμῖν</span> <span class=\"greek\">παρηγγείλαμεν</span>, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1TH.4.11\" target=\"_blank\" rel=\"noopener noreferrer\">1 Th 4:11</a>; passiva <span class=\"greek\">τὰ</span> <span class=\"greek\">παρηγγελμένα</span> <span class=\"greek\">τινί</span>, «Aquilo que foi ordenado a alguém (fazer)», final breve de Marcos. <span class=\"greek\">τινί</span> seguido de <span class=\"greek\">λέγων</span> e discurso direto, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.10.5\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 10:5</a>. <span class=\"greek\">τινί</span> <span class=\"greek\">τι</span> com <span class=\"greek\">ὅτι</span> seguido de discurso direto, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/2TH.3.10\" target=\"_blank\" rel=\"noopener noreferrer\">2 Th 3:10</a>.—<span class=\"greek\">τινί</span> seguido de infinitivo aoristo (Philo, Poster. Cai. 29; Jos., C. Ap. 1, 244; Just., D. 14, 3; Hippol., Ref. 5, 26, 22. Ver também Iren. 1, prol. 2 [Harv. I 4, 5]), <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.15.35\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 15:35</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MRK.8.6\" target=\"_blank\" rel=\"noopener noreferrer\">Mk 8:6</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.8.29\" target=\"_blank\" rel=\"noopener noreferrer\">Lk 8:29</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.10.42\" target=\"_blank\" rel=\"noopener noreferrer\">Ac 10:42</a>; 16:18 (ver Mlt. 119). <span class=\"greek\">τινί</span> seguido de infinitivo presente (1 Km 23:8), <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.16.23\" target=\"_blank\" rel=\"noopener noreferrer\">Ac 16:23</a>; 23:30; 1 Cl 1:3; IPol 5:1. <span class=\"greek\">παραγγέλλειν</span> seguido de infinitivo e <span class=\"greek\">μή</span> passa a significar «Proibir alguém de fazer alguma coisa»: <span class=\"greek\">π</span>. <span class=\"greek\">τινί</span> seguido de infinitivo aoristo, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.5.14\" target=\"_blank\" rel=\"noopener noreferrer\">Lk 5:14</a>; 8:56; sem dativo, facilmente suprível pelo contexto, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.23.22\" target=\"_blank\" rel=\"noopener noreferrer\">Ac 23:22</a>. <span class=\"greek\">π</span>. <span class=\"greek\">τινί</span> seguido de infinitivo presente (cf. uma inscrição de Dionysopolis [Ramsay, ET 14, 1903, 159] <span class=\"greek\">παραγγέλλω</span> <span class=\"greek\">πᾶσι</span>, <span class=\"greek\">μὴ</span> <span class=\"greek\">καταφρονεῖν</span> <span class=\"greek\">τοῦ</span> <span class=\"greek\">θεοῦ</span>; Philo, Leg. All. 1, 98; Just., D. 112, 4), <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.9.21\" target=\"_blank\" rel=\"noopener noreferrer\">Lk 9:21</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.1.4\" target=\"_blank\" rel=\"noopener noreferrer\">Ac 1:4</a> (sobre a transição de discurso indireto para direto, cf. Arrian, Anab. 5, 11, 4: Alexandre <span class=\"greek\">παρηγγέλλετο</span> <span class=\"greek\">Κρατέρῳ</span> <span class=\"greek\">μὴ</span> <span class=\"greek\">διαβαίνειν</span> <span class=\"greek\">τὸν</span> <span class=\"greek\">πόρον</span> … <span class=\"greek\">ἢν</span> <span class=\"greek\">Πῶρος</span> <span class=\"greek\">ἐπ</span>’ <span class=\"greek\">ἐμὲ</span> <span class=\"greek\">ἄγῃ</span> [a oração final é pronunciada por Alexandre]); <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1TI.1.3\" target=\"_blank\" rel=\"noopener noreferrer\">1 Ti 1:3</a>; 6:17 (ver B-D-F §409, 1); sem dativo (Jos., Ant. 19, 311), 1 Cl 27:2, dativo suprível pelo contexto em <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.4.18\" target=\"_blank\" rel=\"noopener noreferrer\">Ac 4:18</a>; 5:40. <span class=\"greek\">παραγγελίᾳ</span> <span class=\"greek\">παρηγγείλαμεν</span> <span class=\"greek\">ὑμῖν</span> <span class=\"greek\">μὴ</span> <span class=\"greek\">διδάσκειν</span>, v. 28.—<span class=\"greek\">τινί</span> seguido de acusativo e infinitivo 1.º aoristo, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1CO.7.10\" target=\"_blank\" rel=\"noopener noreferrer\">1 Cor 7:10</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1TI.6.13\" target=\"_blank\" rel=\"noopener noreferrer\">1 Ti 6:13f</a>; infinitivo presente, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.17.30\" target=\"_blank\" rel=\"noopener noreferrer\">Ac 17:30</a>; 23:30; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/2TH.3.6\" target=\"_blank\" rel=\"noopener noreferrer\">2 Th 3:6</a>.—Seguido de <span class=\"greek\">ἵνα</span> (ver <span class=\"greek\">ἵνα</span> II 1a<span class=\"greek\">δ</span>), <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/2TH.3.12\" target=\"_blank\" rel=\"noopener noreferrer\">2 Th 3:12</a>. <span class=\"greek\">παρήγγειλεν</span> <span class=\"greek\">αὐτοῖς</span> <span class=\"greek\">ἵνα</span> <span class=\"greek\">μηδὲν</span> <span class=\"greek\">αἴρωσιν</span>, «Proibiu-lhes que levassem qualquer coisa», <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MRK.6.8\" target=\"_blank\" rel=\"noopener noreferrer\">Mk 6:8</a>.—DELG s.v. <span class=\"greek\">ἄγγελος</span>. M-M. TW. Spicq.</p></section></article>\n<article class=\"entry-card\" id=\"entry-bdag-0268-11\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">παράγγελμα, ατος, τό</h1><div class=\"entry-meta\"><span>substantivo neutro</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução integral</div><p class=\"entry-text\"><span class=\"greek\">παράγγελμα</span>, <span class=\"greek\">ατος</span>, <span class=\"greek\">τό</span> (Aeschyl., Thu. e posteriores; SIG 985, 12; 34; PAmh 50, 5; PLond III, 904, 36 p. 126 [104 d.C.]; PGM 4, 749; 1 Km 22:14; Philo; Jos., Ant. 16, 43, C. Ap. 1, 178; Just., D. 10, 2; Tat.), ordem que determina algo a ser feito, ordem, determinação, instrução, preceito, especialmente o decreto de um governante (Jos., Bell. 6, 383), 1 Cl 13:3 (com <span class=\"greek\">ἐντολή</span>). <span class=\"greek\">ποιεῖν</span> <span class=\"greek\">τὰ</span> <span class=\"greek\">τοῦ</span> <span class=\"greek\">Χριστοῦ</span> <span class=\"greek\">π</span>., «Cumprir os preceitos de Cristo», 49:1.—DELG s.v. <span class=\"greek\">ἄγγελος</span>. M-M s.v. <span class=\"greek\">παραγγελία</span>.</p></section></article>\n<article class=\"entry-card\" id=\"entry-bdag-0268-12\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">παραγίνομαι</h1><div class=\"entry-meta\"><span>verbo</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução integral</div><p class=\"entry-text\"><span class=\"greek\">παραγίνομαι</span>, imperfeito, 3.ª pessoa plural <span class=\"greek\">παρεγίνοντο</span>; 2.º aoristo <span class=\"greek\">παρεγενόμην</span> e <span class=\"greek\">παρεγενήθην</span> na LXX; perfeito <span class=\"greek\">παραγέγονα</span> na LXX; mais-que-perfeito, 3.ª pessoa singular <span class=\"greek\">παραγεγόνει</span>; infinitivo <span class=\"greek\">παραγεγενῆσθαι</span> (Just.) (Hom. e posteriores).<br>\n① Estar em movimento de modo a alcançar um lugar determinado, aproximar-se, vir, chegar, estar presente (Aristoph., Hdt. e outros; Vi. Aesopi G 7 Isis; inscrições, papiros, LXX).<br>\nⓐ Referente a pessoas, seguido de <span class=\"greek\">εἰς</span> e acusativo de lugar (Hdt.; SIG 474, 13f <span class=\"greek\">παραγεγονὼς</span> <span class=\"greek\">δὲ</span> [<span class=\"greek\">καὶ</span> <span class=\"greek\">εἰς</span> <span class=\"greek\">τὴν</span> <span class=\"greek\">πό</span>]<span class=\"greek\">λιν</span>; POxy 743, 23 [2 a.C.]; PRyl 232, 3; Ex 16:35; Josh 24:11; Philo, Mos. 1, 86), <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.2.1\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 2:1</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/JHN.8.2\" target=\"_blank\" rel=\"noopener noreferrer\">J 8:2</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.9.26\" target=\"_blank\" rel=\"noopener noreferrer\">Ac 9:26</a>; 13:14 (com <span class=\"greek\">ἀπὸ</span> <span class=\"greek\">τ</span>. <span class=\"greek\">Πέργης</span>; cf. Jos., Ant. 18, 110); 15:4; AcPl Ant 13, 1 (= Aa I 236, 6); AcPl Cor 1:2. Também <span class=\"greek\">ἐν</span> com dativo de lugar (POxy 1185, 26; BGU 286, 6; Just., D. 51, 2), <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.9.26\" target=\"_blank\" rel=\"noopener noreferrer\">Ac 9:26</a>, variante textual; ITr 1:1. Seguido de <span class=\"greek\">ἐπί</span> <span class=\"greek\">τινα</span>, «Vir contra alguém», principalmente com intenção hostil (Thu. 2, 95, 3; 2 Macc 4:34; 8:16; 11:2; 12:6; 15:24.—<span class=\"greek\">ἐπί</span> 12b), <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.22.52\" target=\"_blank\" rel=\"noopener noreferrer\">Lk 22:52</a>. Seguido de <span class=\"greek\">πρός</span> <span class=\"greek\">τινα</span> (Lucian, Philops. 6; PCairZen 214, 5 [254 a.C.] <span class=\"greek\">πρὸς</span> <span class=\"greek\">ἡμᾶς</span>; PSI 341, 4; PEleph 9, 4; Ex 2:18; Judg 8:15; Jos., Ant. 6, 131), <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.7.4\" target=\"_blank\" rel=\"noopener noreferrer\">Lk 7:4</a>, 20; 8:19; 22:52, variante textual; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.20.18\" target=\"_blank\" rel=\"noopener noreferrer\">Ac 20:18</a>. <span class=\"greek\">φίλος</span> <span class=\"greek\">παρεγένετο</span> <span class=\"greek\">ἐξ</span> <span class=\"greek\">ὁδοῦ</span> <span class=\"greek\">πρός</span> <span class=\"greek\">με</span>, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.11.6\" target=\"_blank\" rel=\"noopener noreferrer\">Lk 11:6</a> (<span class=\"greek\">παραγίνεσθαι</span> <span class=\"greek\">ἐκ</span> como em SIG 663, 4; PMagd 1, 10 [III a.C.]; Gen 35:9; 1 Macc 5:14; Jos., Vi. 248 <span class=\"greek\">ἐκ</span> <span class=\"greek\">τῆς</span> <span class=\"greek\">ὁδοῦ</span> <span class=\"greek\">παρεγενόμην</span>). <span class=\"greek\">παραγίνεται</span> <span class=\"greek\">ὁ</span> <span class=\"greek\">Ἰησοῦς</span> <span class=\"greek\">ἀπὸ</span> <span class=\"greek\">τῆς</span> <span class=\"greek\">Γαλιλαίας</span> <span class=\"greek\">ἐπὶ</span> <span class=\"greek\">τὸν</span> <span class=\"greek\">Ἰορδάνην</span> <span class=\"greek\">πρὸς</span> <span class=\"greek\">τὸν</span> <span class=\"greek\">Ἰωάννην</span>, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.3.13\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 3:13</a> (<span class=\"greek\">π</span>. <span class=\"greek\">ἐπί</span> com acusativo de lugar como em SIG 633, 85 e outros; Sb 3925, 4; Jdth 6:11; 14:13; Bel 15). <span class=\"greek\">ἐνθάδε</span>, AcPlCor 1:16. Em uso absoluto, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MRK.14.43\" target=\"_blank\" rel=\"noopener noreferrer\">Mk 14:43</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.14.21\" target=\"_blank\" rel=\"noopener noreferrer\">Lk 14:21</a>; 19:16; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/JHN.3.23\" target=\"_blank\" rel=\"noopener noreferrer\">J 3:23</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.5.21\" target=\"_blank\" rel=\"noopener noreferrer\">Ac 5:21f</a>, 25; 9:39; 10:33; 11:23; 14:27; 17:10; 18:27; 21:18; 23:16, 35; 24:17, 24; 25:7; 28:21; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1CO.16.3\" target=\"_blank\" rel=\"noopener noreferrer\">1 Cor 16:3</a>; 1 Cl 12:6; IRo 6:2; Hs 9, 5, 7; AcPlCor 1:7.<br>\nⓑ Sobre coisas ensinadas: <span class=\"greek\">ἐντολὰς</span> … <span class=\"greek\">τὰς</span> … <span class=\"greek\">ἀπ</span>’ <span class=\"greek\">αὐτῆς</span> <span class=\"greek\">παραγινομένας</span> <span class=\"greek\">τῆς</span> <span class=\"greek\">ἀληθείας</span>, «Instruções que procedem diretamente da verdade», Papias (2:3). Por vezes, «vir» tem, antes, o sentido de:<br>\n② Fazer uma aparição pública, aparecer, sobre João Batista, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.3.1\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 3:1</a>. Sobre Jesus, seguido de infinitivo de finalidade (cf. 1 Macc 4:46), <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.12.51\" target=\"_blank\" rel=\"noopener noreferrer\">Lk 12:51</a>. <span class=\"greek\">Χριστὸς</span> <span class=\"greek\">παραγενόμενος</span> <span class=\"greek\">ἀρχιερεύς</span>, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/HEB.9.11\" target=\"_blank\" rel=\"noopener noreferrer\">Hb 9:11</a>.<br>\n③ Vir ajudar, estar ao lado, acudir (trágicos; Thu. 3, 54, 4; Pla., Rep. 2, 368b): <span class=\"greek\">οὐδείς</span> <span class=\"greek\">μοι</span> <span class=\"greek\">παρεγένετο</span>, «Ninguém esteve a meu lado», <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/2TI.4.16\" target=\"_blank\" rel=\"noopener noreferrer\">2 Ti 4:16</a>.—DELG s.v. <span class=\"greek\">γίγνομαι</span>. M-M.</p></section></article>\n<article class=\"entry-card\" id=\"entry-bdag-0268-13\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">παράγω</h1><div class=\"entry-meta\"><span>verbo</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução integral</div><p class=\"entry-text\"><span class=\"greek\">παράγω</span>, imperfeito <span class=\"greek\">παρῆγον</span>; 2.º aoristo <span class=\"greek\">παρήγαγον</span> na LXX. Passiva: aoristo, 3.ª pessoa singular <span class=\"greek\">παρήχθη</span> na LXX (Pind., Hdt. e posteriores).<br>\n① Mover-se ao longo de algo e assim deixar uma posição, ir embora: <span class=\"greek\">παρῆγεν</span> <span class=\"greek\">οὕτως</span>, «Assim ele se retirou», <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/JHN.8.59\" target=\"_blank\" rel=\"noopener noreferrer\">J 8:59</a>, variante textual (dada essa variante, o <span class=\"greek\">παράγων</span> de 9:1 [ver 3 abaixo] também pertenceria a esta acepção). <span class=\"greek\">ἐκεῖθεν</span>, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.9.9\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 9:9</a>, 27.<br>\n② Introduzir algo de natureza estranha à condição ou circunstância presente, trazer, introduzir: <span class=\"greek\">παράγουσι</span> <span class=\"greek\">φόβους</span> <span class=\"greek\">ἀνθρωπίνους</span>, 2 Cl 10:3 (ver <span class=\"greek\">φόβος</span> 2a<span class=\"greek\">α</span>). (Ativa transitiva com diversos sentidos: BGU 1139, 19 [5 a.C.]; 1 Km 16:9f; Jos., Ant. 5, 97; 20, 200).<br>\n③ Passar por um ponto de referência, passar ao lado (Polyb. 5, 18, 4; Appian, Bell. Civ. 2, 62 §259 <span class=\"greek\">θεοῦ</span> <span class=\"greek\">παράγοντος</span> = «Como se um deus tivesse passado» [e atingido Labieno de cegueira]; Coll. Alex., Lyr. Adesp. 37, 25 <span class=\"greek\">ἐὰν</span> … <span class=\"greek\">μνήματα</span> <span class=\"greek\">κωφὰ</span> <span class=\"greek\">παράγῃς</span>; Menand., Dyscol. 556 e outros; CIG 2129, 2; PTebt 17, 4; 2 Km 15:18; Ps 128:8; 3 Macc 6:16), <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.20.30\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 20:30</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MRK.2.14\" target=\"_blank\" rel=\"noopener noreferrer\">Mk 2:14</a>; 15:21; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/JHN.9.1\" target=\"_blank\" rel=\"noopener noreferrer\">J 9:1</a>. <span class=\"greek\">π</span>. <span class=\"greek\">παρὰ</span> <span class=\"greek\">τὴν</span> <span class=\"greek\">θάλασσαν</span>, «Passar ao longo do lago», <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MRK.1.16\" target=\"_blank\" rel=\"noopener noreferrer\">Mk 1:16</a>. Cf. ELohmeyer, ‘Und Jesus ging vorüber’: NThT 23, ’34, 206–24.<br>\n④ Deixar de existir, passar, desaparecer, em linguagem figurada.<br>\nⓐ Ativa (Ps 143:4), <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1CO.7.31\" target=\"_blank\" rel=\"noopener noreferrer\">1 Cor 7:31</a>.<br>\nⓑ Passiva, com sentido ativo (cf. 2 Esdr 9:2 <span class=\"greek\">παρήχθη</span> <span class=\"greek\">σπέρμα</span> <span class=\"greek\">τὸ</span> <span class=\"greek\">ἅγιον</span>): <span class=\"greek\">ἡ</span> <span class=\"greek\">σκοτία</span> <span class=\"greek\">παράγεται</span>, «As trevas estão passando», <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1JN.2.8\" target=\"_blank\" rel=\"noopener noreferrer\">1J 2:8</a>; cf. v. 17 (<span class=\"greek\">ὁ</span> <span class=\"greek\">κόσμος</span> <span class=\"greek\">παραλεύσεται</span>, TestJob 33:4).—M-M. TW.</p></section></article>\n<article class=\"entry-card\" id=\"entry-bdag-0268-14\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">παραδειγματίζω</h1><div class=\"entry-meta\"><span>verbo</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução integral</div><p class=\"entry-text\"><span class=\"greek\">παραδειγματίζω</span> (<span class=\"greek\">παράδειγμα</span>, «modelo»), subjuntivo do 1.º aoristo <span class=\"greek\">παραδειγματίσῃς</span>, GJs 20:2, códices; infinitivo do 1.º aoristo <span class=\"greek\">παραδειγματίσαι</span>. Passiva: futuro, 2.ª pessoa plural <span class=\"greek\">παραδειγματισθήσεσθε</span>, Da 2:5; infinitivo do 1.º aoristo <span class=\"greek\">παραδειγματισθῆναι</span>, LXX (Polyb. e outros; LXX; PsSol 2:12). (Na maioria dos casos = «Fazer de alguém um exemplo público» mediante punição [Polyb. 2, 60, 7; 29, 19, 5; LXX]; posteriormente, também sem a ideia de punição), desonrar alguém publicamente, expor, fazer de alguém um exemplo (Plut., Mor. 520b, sobre Arquíloco, que manchou a própria reputação com ataques injuriosos a mulheres), com <span class=\"greek\">τινά</span>, alguém, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.1.19\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 1:19</a>, variante textual (ver <span class=\"greek\">δειγματίζω</span>); Salomé ora <span class=\"greek\">μὴ</span> <span class=\"greek\">παραδειγματίσῃς</span> <span class=\"greek\">με</span> <span class=\"greek\">τοῖς</span> <span class=\"greek\">υἱοῖς</span> <span class=\"greek\">Ἰσραήλ</span>, GJs 20:2, códices; com <span class=\"greek\">ἀνασταυροῦν</span>, «Expor ao desprezo», <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/HEB.6.6\" target=\"_blank\" rel=\"noopener noreferrer\">Hb 6:6</a>.—DELG s.v. <span class=\"greek\">δείκνυμι</span>. M-M. TW. Spicq. Sv.</p></section></article>\n<article class=\"entry-card\" id=\"entry-bdag-0268-15\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">παράδεισος, ου, ὁ</h1><div class=\"entry-meta\"><span>substantivo masculino</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução integral</div><p class=\"entry-text\"><span class=\"greek\">παράδεισος</span>, <span class=\"greek\">ου</span>, <span class=\"greek\">ὁ</span> (antigo persa pairidaêza [forma avéstica; ver WHinz, Altiranisches Sprachgut der Nebenüberlieferungen, ’75, 179] = «recinto cercado»; hebraico <span class=\"hebrew\" dir=\"rtl\">פַּרְדֵּס</span>. No grego desde X.; em geral, «jardim»; frequente nos papiros, ver também New Docs 2, 201), em nossa literatura, exceto GJs 2:4, não se refere a jardim comum (como também TestAbr A 4 p. 80, 23 [Stone p. 8, 23] ApcrEzk Fgm. a) nem a parque, mas somente:<br>\n① Jardim do Éden, paraíso (Gen 2f; Philo; Jos., Ant. 1, 37; SibOr 1, 24; 26; 30; Iren. 5, 5, 1 [Harv. II 331, 3]; Orig., C. Cels. 7, 50, 31; Hippol., Did., Theoph. Ant. 2, 22 [p. 154, 21]), literalmente, Dg 12:3, e no mesmo contexto figuradamente, acerca daqueles que amam a Deus, <span class=\"greek\">οἱ</span> <span class=\"greek\">γενόμενοι</span> <span class=\"greek\">παράδεισος</span> <span class=\"greek\">τρυφῆς</span>, «Os que se mostram um paraíso exuberante», na medida em que permitem que árvores carregadas de frutos cresçam em seu interior, 12:1 (cf. PsSol 14:3).<br>\n② Lugar transcendente de bem-aventurança, paraíso (<span class=\"greek\">ὁ</span> <span class=\"greek\">παράδεισος</span> <span class=\"greek\">τῆς</span> <span class=\"greek\">δικαιοσύνης</span> figura como tal em En 32:3; cf. 20:7; TestLevi 18:10; SibOr Fgm. 3, 48 e outras passagens dos pseudepígrafos do AT não preservadas em grego, bem como outras fontes na bibliografia citada abaixo.—Dssm., B 146 [BS 148]), <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.23.43\" target=\"_blank\" rel=\"noopener noreferrer\">Lk 23:43</a> (JWeisengoff, EcclRev 103, ’40, 163–67). <span class=\"greek\">ὡς</span> <span class=\"greek\">ἐν</span> <span class=\"greek\">π</span>., «Como no paraíso», AcPl Ha 3, 23. Mais plenamente, <span class=\"greek\">ὁ</span> <span class=\"greek\">π</span>. <span class=\"greek\">τοῦ</span> <span class=\"greek\">θεοῦ</span>, «O paraíso de Deus» (Gen 13:10; Ez 28:13; 31:8; PGM 4, 3027 <span class=\"greek\">ἐν</span> <span class=\"greek\">τῷ</span> <span class=\"greek\">ἁγίῳ</span> <span class=\"greek\">ἑαυτοῦ</span> [=<span class=\"greek\">τ</span>. <span class=\"greek\">θεοῦ</span>] <span class=\"greek\">παραδείσῳ</span>), <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/REV.2.7\" target=\"_blank\" rel=\"noopener noreferrer\">Rv 2:7</a>. <span class=\"greek\">ἁρπάζεσθαι</span> <span class=\"greek\">εἰς</span> <span class=\"greek\">τὸν</span> <span class=\"greek\">π</span>., «Ser arrebatado ao paraíso», <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/2CO.12.4\" target=\"_blank\" rel=\"noopener noreferrer\">2 Cor 12:4</a>.—Ver <span class=\"greek\">οὐρανός</span> 1e e <span class=\"greek\">τρίτος</span> 1a. Além disso, Bousset, Rel.3 282ff; 488ff; PVolz, D. Eschatologie der jüd. Gemeinde im ntl. Zeitalter ’34, 417f; Billerb. IV 1118–65; Windisch sobre <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/2CO.12.4\" target=\"_blank\" rel=\"noopener noreferrer\">2 Cor 12:4</a>; AWabnitz, Le Paradis du Hadès: RTQR 19, 1910, 328–31; 410–14; 20, 1911, 130–38.—DELG. M-M. TW.</p></section></article>\n<article class=\"entry-card\" id=\"entry-bdag-0268-16\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">παραδέχομαι</h1><div class=\"entry-meta\"><span>verbo</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução integral</div><p class=\"entry-text\"><span class=\"greek\">παραδέχομαι</span>, futuro <span class=\"greek\">παραδέξομαι</span>; 1.º aoristo <span class=\"greek\">παρεδεξάμην</span>. Passiva: 1.º futuro passivo <span class=\"greek\">παραδεχθήσομαι</span>; 1.º aoristo <span class=\"greek\">παρεδέχθην</span> (Hom. e posteriores).<br>\n① Reconhecer que alguma coisa é correta, aceitar, com uma coisa como objeto no acusativo (Epict. 3, 12, 15; BGU 1119, 54 [I d.C.] <span class=\"greek\">τὴν</span> <span class=\"greek\">συντίμησιν</span>; PRyl 229, 16; PFay 125, 10; Ex 23:1; 3 Macc 7:12; Just., D. 12, 2): <span class=\"greek\">τὸν</span> <span class=\"greek\">λόγον</span>, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MRK.4.20\" target=\"_blank\" rel=\"noopener noreferrer\">Mk 4:20</a> (Diocles 112 p. 163, 18 <span class=\"greek\">παραδ</span>. <span class=\"greek\">τὸν</span> <span class=\"greek\">λόγον</span>; Plut., Mor. 47e; Philo, Leg. All. 3, 199). <span class=\"greek\">ἔθη</span>, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.16.21\" target=\"_blank\" rel=\"noopener noreferrer\">Ac 16:21</a>. <span class=\"greek\">μαρτυρίαν</span>, 22:18. <span class=\"greek\">τὶ</span> <span class=\"greek\">ἄλλο</span>, AcPlCor 2:34. <span class=\"greek\">κατηγορίαν</span>, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1TI.5.19\" target=\"_blank\" rel=\"noopener noreferrer\">1 Ti 5:19</a> (Sextus 259 <span class=\"greek\">διαβολὰς</span> <span class=\"greek\">κατὰ</span> <span class=\"greek\">φιλοσόφου</span> <span class=\"greek\">μὴ</span> <span class=\"greek\">παραδέχου</span>). Receber ensinamentos errôneos, IEph 9:1. (Em oposição a <span class=\"greek\">παραιτεῖσθαι</span>), <span class=\"greek\">τὰ</span> <span class=\"greek\">κτισθέντα</span>, Dg 4:2.<br>\n② Aceitar a presença de alguém de maneira hospitaleira, receber, acolher, com uma pessoa como objeto no acusativo (POxy 492, 8; 14; 1676, 28; BGU 27:10; Jos., C. Ap. 2, 256; 258), dissidentes, ISm 4:1. <span class=\"greek\">θεὸν</span> <span class=\"greek\">τὸν</span> <span class=\"greek\">παραδεχόμενον</span> <span class=\"greek\">ἡμάς</span> (com <span class=\"greek\">καλεῖν</span>), 2 Cl 16:1. Na passiva (2 Macc 4:22, Cod. V), <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.15.4\" target=\"_blank\" rel=\"noopener noreferrer\">Ac 15:4</a> (variante textual <span class=\"greek\">ἀπεδέχθησαν</span>). Receber de volta esposa repudiada por adultério, Hm 4, 1, 8a; passiva, 4, 1, 7; 8b. Sobre um cidadão que deseja retornar à cidade natal depois de viver em terra estrangeira, na passiva, Hs 1:5.—Correspondente a <span class=\"hebrew\" dir=\"rtl\">רָצָה</span>, «Receber favoravelmente» = «amar» (Pr 3:12), <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/HEB.12.6\" target=\"_blank\" rel=\"noopener noreferrer\">Hb 12:6</a>; 1 Cl 56:4.—M-M.</p></section></article>\n<article class=\"entry-card\" id=\"entry-bdag-0268-17\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">παραδιατριβή, ῆς, ἡ</h1><div class=\"entry-meta\"><span>substantivo feminino</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução integral</div><p class=\"entry-text\"><span class=\"greek\">παραδιατριβή</span>, <span class=\"greek\">ῆς</span>, <span class=\"greek\">ἡ</span>, desperdício de tempo com assuntos sem importância, ocupação inútil, no plural, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1TI.6.5\" target=\"_blank\" rel=\"noopener noreferrer\">1 Ti 6:5</a>, variante textual (cf. Field, Notes 211).—M-M.</p></section></article>\n<article class=\"entry-card\" id=\"entry-bdag-0268-18\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">παραδίδωμι</h1><div class=\"entry-meta\"><span>verbo</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução integral</div><p class=\"entry-text\"><span class=\"greek\">παραδίδωμι</span> (Pind., Hdt. e posteriores), presente, 3.ª pessoa singular <span class=\"greek\">παραδίδει</span> (-<span class=\"greek\">δίδη</span> nos códices [ApcEsdr 3:12 p. 27, 23 Tdf.]); subjuntivo, 3.ª pessoa singular <span class=\"greek\">παραδιδῷ</span> e <span class=\"greek\">παραδιδοῖ</span>, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1CO.15.24\" target=\"_blank\" rel=\"noopener noreferrer\">1 Cor 15:24</a> (B-D-F §95, 2; W-S. §14, 12; Mlt-H. 204); particípio <span class=\"greek\">παραδιδούς</span>; imperfeito, 3.ª pessoa singular <span class=\"greek\">παρεδίδου</span>, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.8.3\" target=\"_blank\" rel=\"noopener noreferrer\">Ac 8:3</a> e <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1PE.2.23\" target=\"_blank\" rel=\"noopener noreferrer\">1 Pt 2:23</a>, plural <span class=\"greek\">παρεδίδουν</span>, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.16.4\" target=\"_blank\" rel=\"noopener noreferrer\">Ac 16:4</a>, variante textual; 27:1, e <span class=\"greek\">παρεδίδοσαν</span>, 16:4 (B-D-F §94, 1; Mlt-H. 202); futuro <span class=\"greek\">παραδώσω</span>; 1.º aoristo <span class=\"greek\">παρέδωκα</span>; indicativo do 2.º aoristo <span class=\"greek\">παρέδοσαν</span>, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.1.2\" target=\"_blank\" rel=\"noopener noreferrer\">Lk 1:2</a>; subjuntivo do 2.º aoristo, 3.ª pessoa singular <span class=\"greek\">παραδῷ</span> e <span class=\"greek\">παραδοῖ</span>, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MRK.4.29\" target=\"_blank\" rel=\"noopener noreferrer\">Mk 4:29</a>; 14:10, 11; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/JHN.13.2\" target=\"_blank\" rel=\"noopener noreferrer\">J 13:2</a> (B-D-F §95, 2; Mlt-H. 210f); imperativo <span class=\"greek\">παράδος</span>, particípio <span class=\"greek\">παραδούς</span>; perfeito <span class=\"greek\">παραδέδωκα</span>, particípio <span class=\"greek\">παραδεδωκώς</span> (<a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.15.26\" target=\"_blank\" rel=\"noopener noreferrer\">Ac 15:26</a>); mais-que-perfeito, 3.ª pessoa plural <span class=\"greek\">παραδεδώκεισαν</span>, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MRK.15.10\" target=\"_blank\" rel=\"noopener noreferrer\">Mk 15:10</a> (sobre a ausência de aumento, ver B-D-F §66, 1; Mlt-H. 190). Passiva: imperfeito, 3.ª pessoa singular <span class=\"greek\">παρεδίδετο</span>, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1CO.11.23\" target=\"_blank\" rel=\"noopener noreferrer\">1 Cor 11:23b</a> (-<span class=\"greek\">δίδοτο</span> também é atestado; B-D-F §94, 1; Mlt-H. 206); 1.º futuro <span class=\"greek\">παραδοθήσομαι</span>; 1.º aoristo <span class=\"greek\">παρεδόθην</span>; perfeito, 3.ª pessoa singular <span class=\"greek\">παραδέδοται</span>, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.4.6\" target=\"_blank\" rel=\"noopener noreferrer\">Lk 4:6</a>, particípio <span class=\"greek\">παραδεδομένος</span> (<a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.14.26\" target=\"_blank\" rel=\"noopener noreferrer\">Ac 14:26</a>).<br>\n① Transferir algo pelo qual se tem interesse pessoal relativamente forte, entregar, dar, confiar.<br>\nⓐ Uma coisa, <span class=\"greek\">τινί</span> <span class=\"greek\">τι</span> (Jos., Ant 4, 83; Mel., P. 42, 290; 292; 294): <span class=\"greek\">τάλαντά</span> <span class=\"greek\">μοι</span>, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.25.20\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 25:20</a>, 22. <span class=\"greek\">αὐτοῖς</span> <span class=\"greek\">τὰ</span> <span class=\"greek\">ὑπάρχοντα</span> <span class=\"greek\">αὐτοῦ</span>, v. 14. <span class=\"greek\">ὑμῖν</span> <span class=\"greek\">τὴν</span> <span class=\"greek\">γῆν</span>, 1 Cl 12:5. <span class=\"greek\">τινὶ</span> <span class=\"greek\">τὴν</span> <span class=\"greek\">κτίσιν</span>, Hv 3, 4, 1; <span class=\"greek\">λίθους</span>, Hs 9, 7, 1; <span class=\"greek\">ἀμπελῶνα</span>, 5, 6, 2. Também no sentido de devolver, restituir, ceder (X., Hell. 2, 3, 7 <span class=\"greek\">τινί</span> <span class=\"greek\">τι</span>): <span class=\"greek\">αὐτῷ</span> <span class=\"greek\">τὴν</span> <span class=\"greek\">παρακαταθήκην</span> <span class=\"greek\">ἣν</span> <span class=\"greek\">ἔλαβον</span>, Hm 3:2.—Passiva, com a coisa facilmente subentendida pelo contexto: <span class=\"greek\">ἐμοὶ</span> <span class=\"greek\">παραδέδοται</span>, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.4.6\" target=\"_blank\" rel=\"noopener noreferrer\">Lk 4:6</a>.—<span class=\"greek\">παρέδωκεν</span> <span class=\"greek\">τὸ</span> <span class=\"greek\">πνεῦμα</span>, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/JHN.19.30\" target=\"_blank\" rel=\"noopener noreferrer\">J 19:30</a> (ApcMos 42; cf. TestAbr B 12 p. 117, 4f [Stone p. 82] <span class=\"greek\">Σαρρα</span> … <span class=\"greek\">παρέδωκε</span> <span class=\"greek\">τὴν</span> <span class=\"greek\">ψυχήν</span>; ParJer 9:8; ApcEsdr 7:14), dispensa dativo: «Ele entregou voluntariamente seu espírito». <span class=\"greek\">ἄνθρωποι</span> <span class=\"greek\">παραδεδωκότες</span> <span class=\"greek\">τὰς</span> <span class=\"greek\">ψυχὰς</span> <span class=\"greek\">αὐτῶν</span> <span class=\"greek\">ὑπὲρ</span> <span class=\"greek\">τοῦ</span> <span class=\"greek\">ὀνόματος</span> <span class=\"greek\">τοῦ</span> <span class=\"greek\">κυρίου</span>, «Homens que arriscaram (empenharam, segundo Field, Notes 124) a própria vida pelo nome do Senhor», <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.15.26\" target=\"_blank\" rel=\"noopener noreferrer\">Ac 15:26</a>. <span class=\"greek\">καὶ</span> <span class=\"greek\">ἐὰν</span> <span class=\"greek\">παραδῶ</span> <span class=\"greek\">τὸ</span> <span class=\"greek\">σῶμά</span> <span class=\"greek\">μου</span> <span class=\"greek\">ἵνα</span> <span class=\"greek\">καυθήσομαι</span>, «E ainda que eu entregue meu corpo para ser queimado», <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1CO.13.3\" target=\"_blank\" rel=\"noopener noreferrer\">1 Cor 13:3</a> (Maximus Tyr. 1, 9i <span class=\"greek\">τῇ</span> <span class=\"greek\">Αἴτνῃ</span> <span class=\"greek\">αὐτοῦ</span> <span class=\"greek\">παραδοὺς</span> <span class=\"greek\">σῶμα</span>; Syntipas p. 60, 11 <span class=\"greek\">πυρὶ</span> <span class=\"greek\">σεαυτὴν</span> <span class=\"greek\">παραδίδως</span>). <span class=\"greek\">ὅταν</span> <span class=\"greek\">παραδιδοῖ</span> <span class=\"greek\">τ</span>. <span class=\"greek\">βασιλείαν</span> <span class=\"greek\">τῷ</span> <span class=\"greek\">θεῷ</span>, «Quando (Cristo) entregar a realeza a Deus», 15:24.<br>\nⓑ Entregar, transferir, ceder uma pessoa ([latim trado], como termo técnico policial e judicial: «entregar à custódia de», OGI 669, 15; PHib 92, 11; 17; PLille 3, 59 [ambos papiros III a.C.]; PTebt 38, 6 [II a.C.] e outros.—Como termo militar, «render-se»: Paus. 1, 2, 1; X., Cyr. 5, 1, 28; 5, 4, 51), <span class=\"greek\">τινά</span>, alguém, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.10.19\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 10:19</a>; 24:10; 27:18; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MRK.13.11\" target=\"_blank\" rel=\"noopener noreferrer\">Mk 13:11</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.3.13\" target=\"_blank\" rel=\"noopener noreferrer\">Ac 3:13</a>. Passiva, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.4.12\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 4:12</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MRK.1.14\" target=\"_blank\" rel=\"noopener noreferrer\">Mk 1:14</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.21.16\" target=\"_blank\" rel=\"noopener noreferrer\">Lk 21:16</a>. <span class=\"greek\">τινά</span> <span class=\"greek\">τινι</span>, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.5.25\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 5:25</a> (de uma autoridade a outra, como UPZ 124, 19f [II a.C.]; TestAbr B 10 p. 115, 11 [Stone p. 78]); 18:34; 27:2; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MRK.10.33\" target=\"_blank\" rel=\"noopener noreferrer\">Mk 10:33b</a>; cf. 15:1; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.12.58\" target=\"_blank\" rel=\"noopener noreferrer\">Lk 12:58</a>; 20:20; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/JHN.18.30\" target=\"_blank\" rel=\"noopener noreferrer\">J 18:30</a>, 35; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.27.1\" target=\"_blank\" rel=\"noopener noreferrer\">Ac 27:1</a>; 28:16, variante textual; Hs 7:5; 9, 10, 6; passiva, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.18.32\" target=\"_blank\" rel=\"noopener noreferrer\">Lk 18:32</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/JHN.18.36\" target=\"_blank\" rel=\"noopener noreferrer\">J 18:36</a>; Hv 5:3f; Hm 4, 4, 3; Hs 6, 3, 6b; 9, 11, 2; 9, 13, 9; 9, 20, 4; 9, 21, 4. <span class=\"greek\">τὸν</span> <span class=\"greek\">Ἰησοῦν</span> <span class=\"greek\">παρέδωκεν</span> <span class=\"greek\">τῷ</span> <span class=\"greek\">θελήματι</span> <span class=\"greek\">αὐτῶν</span>, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.23.25\" target=\"_blank\" rel=\"noopener noreferrer\">Lk 23:25</a>.—Especialmente a respeito de Judas (ver Brown, Death I 211f, sobre a tendência dos tradutores de obscurecer o paralelismo entre a ação de Judas e a atuação de outros agentes na narrativa da Paixão), cuja informação e ação conduzem à prisão de Jesus, com acusativo e dativo: <span class=\"greek\">ἐγὼ</span> <span class=\"greek\">ὑμῖν</span> <span class=\"greek\">παραδώσω</span> <span class=\"greek\">αὐτόν</span>, «Eu vo-lo entregarei», <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.26.15\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 26:15</a>. Cf. <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MRK.14.10\" target=\"_blank\" rel=\"noopener noreferrer\">Mk 14:10</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.22.4\" target=\"_blank\" rel=\"noopener noreferrer\">Lk 22:4</a>, 6; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/JHN.19.11\" target=\"_blank\" rel=\"noopener noreferrer\">J 19:11</a>. Passiva, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.20.18\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 20:18</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MRK.10.33\" target=\"_blank\" rel=\"noopener noreferrer\">Mk 10:33a</a>. Sem dativo, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.10.4\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 10:4</a>; 26:16, 21, 23; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MRK.3.19\" target=\"_blank\" rel=\"noopener noreferrer\">Mk 3:19</a>; 14:11, 18; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.22.48\" target=\"_blank\" rel=\"noopener noreferrer\">Lk 22:48</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/JHN.6.64\" target=\"_blank\" rel=\"noopener noreferrer\">J 6:64</a>, 71; 12:4; 13:21. Passiva, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.26.24\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 26:24</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MRK.14.21\" target=\"_blank\" rel=\"noopener noreferrer\">Mk 14:21</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.22.22\" target=\"_blank\" rel=\"noopener noreferrer\">Lk 22:22</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1CO.11.23\" target=\"_blank\" rel=\"noopener noreferrer\">1 Cor 11:23b</a> (NRSV e outros traduzem «traído», mas não é certo que, ao referir-se a «entregar», «ceder», «prender» [claramente assim em Posidon.: 87 Fgm. 36, 50 Jac. <span class=\"greek\">παραδοθείς</span>, «rendido»], Paulo esteja sequer pensando na ação de Judas contra Jesus, muito menos interpretando-a como traição; cf. <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.3.13\" target=\"_blank\" rel=\"noopener noreferrer\">Ac 3:13</a> <span class=\"greek\">παρεδώκατε</span>). <span class=\"greek\">ὁ</span> <span class=\"greek\">παραδιδοὺς</span> <span class=\"greek\">αὐτόν</span> (<span class=\"greek\">παραδιδούς</span> <span class=\"greek\">με</span>), «O informante dele (meu)» (sobre o papel de um <span class=\"hebrew\" dir=\"rtl\">מסוֹר</span> na piedade israelita, ver WKlassen, Judas ’96, 62–66; mas em <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.1.18\" target=\"_blank\" rel=\"noopener noreferrer\">Ac 1:18</a> a ação de Judas é caracterizada como <span class=\"greek\">ἀδικία</span>), <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.26.25\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 26:25</a>, 46, 48; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MRK.14.42\" target=\"_blank\" rel=\"noopener noreferrer\">Mk 14:42</a>, 44; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.22.21\" target=\"_blank\" rel=\"noopener noreferrer\">Lk 22:21</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/JHN.13.11\" target=\"_blank\" rel=\"noopener noreferrer\">J 13:11</a>; 18:2, 5. Cf. <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.27.3\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 27:3</a>, 4; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/JHN.21.20\" target=\"_blank\" rel=\"noopener noreferrer\">J 21:20</a>. O artigo com particípio presente denota a notoriedade (cf. o uso de traditor em Tacitus, Histories 4, 24) de Judas na tradição primitiva. Seu ato é avaliado como traição em <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.6.16\" target=\"_blank\" rel=\"noopener noreferrer\">Lk 6:16</a>, ver <span class=\"greek\">προδότης</span>.—<span class=\"greek\">τινὰ</span> <span class=\"greek\">εἰς</span> <span class=\"greek\">χεῖράς</span> <span class=\"greek\">τινος</span>, «Entregar alguém ou algo nas mãos de alguém» (construção semítica, mas com paralelo em latim, cf. Livy 26, 12, 11; Dt 1:27; Jer 33:24; Jdth 6:10; 1 Macc 4:30; 1 Esdr 1:50. Passiva, Jer 39:4, 36, 43; Sir 11:6; Da 7:25, 11:11; TestJob 20:3; ParJer 2:7 <span class=\"greek\">τὴν</span> <span class=\"greek\">πόλιν</span>; AscIs 2:14; cf. Jos., Ant. 2, 20), <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.21.11\" target=\"_blank\" rel=\"noopener noreferrer\">Ac 21:11</a>. Passiva, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.17.22\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 17:22</a>; 26:45; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MRK.9.31\" target=\"_blank\" rel=\"noopener noreferrer\">Mk 9:31</a>; 14:41; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.9.44\" target=\"_blank\" rel=\"noopener noreferrer\">Lk 9:44</a>; 24:7 (NPerrin, JJeremias Festschr., ’70, 204–12); <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.28.17\" target=\"_blank\" rel=\"noopener noreferrer\">Ac 28:17</a>. <span class=\"greek\">ἡ</span> <span class=\"greek\">γῆ</span> <span class=\"greek\">παραδοθήσεται</span> <span class=\"greek\">εἰς</span> <span class=\"greek\">χεῖρας</span> <span class=\"greek\">αὐτοῦ</span>, D 16:4b. Também <span class=\"greek\">ἐν</span> <span class=\"greek\">χειρί</span> <span class=\"greek\">τινος</span> (Judg 7:9; 2 Esdr 9:7; cf. 2 Ch 36:17; 1 Macc 5:50; Just., D. 40, 2 <span class=\"greek\">ὁ</span> <span class=\"greek\">τόπος</span> <span class=\"greek\">τοῖς</span> <span class=\"greek\">ἐχθροῖς</span> <span class=\"greek\">ὑμῶν</span> <span class=\"greek\">παραδοθήσεται</span>), 1 Cl 55:5b.<br>\n—Com indicação do destino ou da finalidade para a qual alguém é entregue: por infinitivo (Jos., Bell. 1, 655), <span class=\"greek\">παραδιδόναι</span> <span class=\"greek\">τινά</span> <span class=\"greek\">τινι</span> <span class=\"greek\">φυλάσσειν</span> <span class=\"greek\">αὐτόν</span>, «Entregar alguém a outra pessoa para que ela o vigie» (X., An. 4, 6, 1), <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.12.4\" target=\"_blank\" rel=\"noopener noreferrer\">Ac 12:4</a>. Com <span class=\"greek\">εἰς</span> locativo (OGI 669, 15 <span class=\"greek\">εἰς</span> <span class=\"greek\">τὸ</span> <span class=\"greek\">πρακτόρειόν</span> <span class=\"greek\">τινας</span> <span class=\"greek\">παρέδοσαν</span>; PGiss 84 II, 18 [II d.C.] <span class=\"greek\">εἰς</span> <span class=\"greek\">τ</span>. <span class=\"greek\">φυλακήν</span>): <span class=\"greek\">εἰς</span> <span class=\"greek\">συνέδρια</span>, «Entregar aos tribunais locais», <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.10.17\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 10:17</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MRK.13.9\" target=\"_blank\" rel=\"noopener noreferrer\">Mk 13:9</a>. <span class=\"greek\">εἰς</span> <span class=\"greek\">τὰς</span> <span class=\"greek\">συναγωγὰς</span> <span class=\"greek\">καὶ</span> <span class=\"greek\">φυλακάς</span>, «Entregar alguém às sinagogas e prisões», <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.21.12\" target=\"_blank\" rel=\"noopener noreferrer\">Lk 21:12</a>. <span class=\"greek\">εἰς</span> <span class=\"greek\">φυλακήν</span>, «Pôr na prisão», <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.8.3\" target=\"_blank\" rel=\"noopener noreferrer\">Ac 8:3</a>; cf. 22:4. Também <span class=\"greek\">εἰς</span> <span class=\"greek\">δεσμωτήριον</span> (referente a um lugar transcendente de punição: cf. PGM 4, 1245ff <span class=\"greek\">ἔξελθε</span>, <span class=\"greek\">δαῖμον</span>, … <span class=\"greek\">παραδίδωμί</span> <span class=\"greek\">σε</span> <span class=\"greek\">εἰς</span> <span class=\"greek\">τὸ</span> <span class=\"greek\">μέλαν</span> <span class=\"greek\">χάος</span> <span class=\"greek\">ἐν</span> <span class=\"greek\">ταῖς</span> <span class=\"greek\">ἀπωλείαις</span>), Hs 9, 28, 7. <span class=\"greek\">ἑαυτοὺς</span> <span class=\"greek\">εἰς</span> <span class=\"greek\">δεσμά</span>, «Entregar-se à prisão», 1 Cl 55:2a. Com <span class=\"greek\">εἰς</span> final (cf. En 97:10 <span class=\"greek\">εἰς</span> <span class=\"greek\">κατάραν</span> <span class=\"greek\">μεγάλην</span> <span class=\"greek\">παρα</span>[<span class=\"greek\">δο</span>]<span class=\"greek\">θήσεσθε</span>): <span class=\"greek\">ἑαυτοὺς</span> <span class=\"greek\">εἰς</span> <span class=\"greek\">δουλείαν</span>, «Entregar-se à escravidão», 55:2b (cf. Just., D. 139, 4). <span class=\"greek\">εἰς</span> <span class=\"greek\">τὸ</span> <span class=\"greek\">σταυρωθῆναι</span>, «Entregar para ser crucificado», <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.26.2\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 26:2</a>. <span class=\"greek\">εἰς</span> <span class=\"greek\">τὸ</span> <span class=\"greek\">ἐμπαῖξαι</span> <span class=\"greek\">κτλ</span>., 20:19. <span class=\"greek\">εἰς</span> <span class=\"greek\">θλῖψιν</span>, 24:9. <span class=\"greek\">εἰς</span> <span class=\"greek\">κρίμα</span> <span class=\"greek\">θανάτου</span>, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.24.20\" target=\"_blank\" rel=\"noopener noreferrer\">Lk 24:20</a>. <span class=\"greek\">εἰς</span> <span class=\"greek\">κρίσιν</span>, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/2PE.2.4\" target=\"_blank\" rel=\"noopener noreferrer\">2 Pt 2:4</a>. <span class=\"greek\">εἰς</span> <span class=\"greek\">θάνατον</span>, «Entregar à morte» (POxy 471, 107 [II d.C.]): <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.10.21\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 10:21</a> (Unknown Sayings, 68 n. 3: denunciando-se uns aos outros); <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MRK.13.12\" target=\"_blank\" rel=\"noopener noreferrer\">Mk 13:12</a>; Hm 12, 1, 2f; na passiva: final de Marcos no manuscrito Freer; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/2CO.4.11\" target=\"_blank\" rel=\"noopener noreferrer\">2 Cor 4:11</a>; 1 Cl 16:13 (Is 53:12); B 12:2; Hs 9, 23, 5. <span class=\"greek\">π</span>. <span class=\"greek\">ἑαυτὸν</span> <span class=\"greek\">εἰς</span> <span class=\"greek\">θάνατον</span>, «Entregar-se à morte», 1 Cl 55:1; figuradamente «Entregar-se à morte», Hs 6, 5, 4. <span class=\"greek\">εἰς</span> <span class=\"greek\">θλῖψιν</span> <span class=\"greek\">θανάτου</span> <span class=\"greek\">παραδίδοσθαι</span>, «Ser entregue ao sofrimento da morte», B 12:5. <span class=\"greek\">π</span>. <span class=\"greek\">τὴν</span> <span class=\"greek\">σάρκα</span> <span class=\"greek\">εἰς</span> <span class=\"greek\">καταφθοράν</span>, «Entregar a própria carne à corrupção», 5:1.—<span class=\"greek\">ἵνα</span> substitui <span class=\"greek\">εἰς</span> final: <span class=\"greek\">τὸν</span> <span class=\"greek\">Ἰησοῦν</span> <span class=\"greek\">παρέδωκεν</span> <span class=\"greek\">ἵνα</span> <span class=\"greek\">σταυρωθῇ</span>, «Entregou Jesus para ser crucificado», <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.27.26\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 27:26</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MRK.15.15\" target=\"_blank\" rel=\"noopener noreferrer\">Mk 15:15</a>; cf. <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/JHN.19.16\" target=\"_blank\" rel=\"noopener noreferrer\">J 19:16</a>.—<span class=\"greek\">π</span>. isolado com o sentido de entregar ao sofrimento, à morte, ao castigo, especialmente em relação a Cristo: <span class=\"greek\">κύριος</span> <span class=\"greek\">παρέδωκεν</span> <span class=\"greek\">αὐτὸν</span> <span class=\"greek\">ὑπὲρ</span> <span class=\"greek\">τῶν</span> <span class=\"greek\">ἁμαρτιῶν</span> <span class=\"greek\">ἡμῶν</span>, 1 Cl 16:7 (cf. Is 53:6).—<a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ROM.8.32\" target=\"_blank\" rel=\"noopener noreferrer\">Ro 8:32</a>. Passiva, 4:25; cf. B 16:5. <span class=\"greek\">π</span>. <span class=\"greek\">ἑαυτὸν</span> <span class=\"greek\">ὑπέρ</span> <span class=\"greek\">τινος</span>, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/GAL.2.20\" target=\"_blank\" rel=\"noopener noreferrer\">Gal 2:20</a> (GBerényi, Biblica 65, ’84, 490–537); <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/EPH.5.25\" target=\"_blank\" rel=\"noopener noreferrer\">Eph 5:25</a>. <span class=\"greek\">παρέδωκεν</span> <span class=\"greek\">ἑαυτὸν</span> <span class=\"greek\">ὑπὲρ</span> <span class=\"greek\">ἡμῶν</span> <span class=\"greek\">προσφορὰν</span> <span class=\"greek\">καὶ</span> <span class=\"greek\">θυσίαν</span> <span class=\"greek\">τῷ</span> <span class=\"greek\">θεῷ</span>, «Entregou-se a Deus por nós como oferta e sacrifício», v. 2.—<span class=\"greek\">π</span>. <span class=\"greek\">τινὰ</span> <span class=\"greek\">τῷ</span> <span class=\"greek\">σατανᾷ</span> <span class=\"greek\">εἰς</span> <span class=\"greek\">ὄλεθρον</span> <span class=\"greek\">τῆς</span> <span class=\"greek\">σαρκός</span>, «Entregar alguém a Satanás para destruição de seu corpo físico», <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1CO.5.5\" target=\"_blank\" rel=\"noopener noreferrer\">1 Cor 5:5</a>. <span class=\"greek\">οὓς</span> <span class=\"greek\">παρέδωκα</span> <span class=\"greek\">τῷ</span> <span class=\"greek\">σατανᾷ</span>, <span class=\"greek\">ἵνα</span>, «Os quais entreguei a Satanás para que», <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1TI.1.20\" target=\"_blank\" rel=\"noopener noreferrer\">1 Ti 1:20</a> (cf. INikaia I, 87, 4f, sobre alguém entregue aos deuses do mundo subterrâneo por violar um túmulo [New Docs 4, 165]; também o exorcismo PGM 5, 334ff <span class=\"greek\">νεκυδαίμων</span>, … <span class=\"greek\">παραδίδωμί</span> <span class=\"greek\">σοι</span> <span class=\"greek\">τὸν</span> <span class=\"greek\">δεῖνα</span>, <span class=\"greek\">ὅπως</span> …; ver bibliografia em <span class=\"greek\">ὄλεθρος</span> 2; também CBruston, L’abandon du pécheur à Satan: RTQR 21, 1912, 450–58; KLatte, Heiliges Recht 1920; LBrun, Segen u. Fluch im Urchr. ’32, 106ff). O anjo do arrependimento diz: <span class=\"greek\">ἐμοὶ</span> <span class=\"greek\">παραδίδονται</span> <span class=\"greek\">εἰς</span> <span class=\"greek\">ἀγαθὴν</span> <span class=\"greek\">παιδείαν</span>, «São entregues a mim para boa instrução», Hs 6, 3, 6a (Demetr. Phaler. [IV/III a.C.] Fgm. 164 FWehrli ’49: Demóstenes <span class=\"greek\">παραδίδωσι</span> <span class=\"greek\">ἑαυτὸν</span> <span class=\"greek\">τῷ</span> <span class=\"greek\">Ἀνδρονίκῳ</span> para ser iniciado na arte dramática).—<span class=\"greek\">ἑαυτοὺς</span> <span class=\"greek\">παρέδωκαν</span> <span class=\"greek\">τῇ</span> <span class=\"greek\">ἀσελγείᾳ</span>, «Entregaram-se à libertinagem», <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/EPH.4.19\" target=\"_blank\" rel=\"noopener noreferrer\">Eph 4:19</a>. <span class=\"greek\">ταῖς</span> <span class=\"greek\">ἐπιθυμίαις</span> <span class=\"greek\">τ</span>. <span class=\"greek\">αἰῶνος</span> <span class=\"greek\">τούτου</span>, Hs 6, 2, 3. <span class=\"greek\">ταῖς</span> <span class=\"greek\">τρυφαῖς</span> <span class=\"greek\">καὶ</span> <span class=\"greek\">ἀπάταις</span>, 6, 2, 4. <span class=\"greek\">παρεδώκατε</span> <span class=\"greek\">ἑαυτοὺς</span> <span class=\"greek\">εἰς</span> <span class=\"greek\">τὰς</span> <span class=\"greek\">ἀκηδίας</span>, Hv 3, 11, 3 (ver <span class=\"greek\">ἀκηδία</span>). Sobre Deus, que castiga os malfeitores: <span class=\"greek\">παρέδωκεν</span> <span class=\"greek\">αὐτοὺς</span> <span class=\"greek\">εἰς</span> <span class=\"greek\">ἀκαθαρσίαν</span>, «Entregou-os à impureza», <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ROM.1.24\" target=\"_blank\" rel=\"noopener noreferrer\">Ro 1:24</a> (quanto à ideia, cf. 1QH 2:16–19. Ver também EKlostermann, ZNW 32, ’33, 1–6 [retribuição]). <span class=\"greek\">εἰς</span> <span class=\"greek\">πάθη</span> <span class=\"greek\">ἀτιμίας</span>, «A paixões infames», v. 26. <span class=\"greek\">εἰς</span> <span class=\"greek\">ἀδόκιμον</span> <span class=\"greek\">νοῦν</span>, «A uma mente reprovável», v. 28. <span class=\"greek\">παρέδωκεν</span> <span class=\"greek\">αὐτοὺς</span> <span class=\"greek\">λατρεύειν</span> <span class=\"greek\">τῇ</span> <span class=\"greek\">στρατιᾷ</span> <span class=\"greek\">τοῦ</span> <span class=\"greek\">οὐρανοῦ</span>, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.7.42\" target=\"_blank\" rel=\"noopener noreferrer\">Ac 7:42</a>. Deus, o inteiramente gracioso, é sujeito da expressão extraordinária (ver bibliografia em <span class=\"greek\">διδαχή</span> 2) <span class=\"greek\">εἰς</span> <span class=\"greek\">ὸ̔ν</span> <span class=\"greek\">παρεδόθητε</span> <span class=\"greek\">τύπον</span> <span class=\"greek\">διδαχῆς</span> = <span class=\"greek\">τῷ</span> <span class=\"greek\">τύπῳ</span> <span class=\"greek\">δ</span>. <span class=\"greek\">εἰς</span> <span class=\"greek\">ὸ̔ν</span> <span class=\"greek\">π</span>., «(Obedientes) à forma de ensino para cuja aprendizagem fostes entregues», isto é, por Deus, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ROM.6.17\" target=\"_blank\" rel=\"noopener noreferrer\">Ro 6:17</a> (cf. inscrição da Transjordânia na época nabateia, NGG Phil.-Hist. Kl. Fachgr. V n.s. I, 1, ’36, p. 3, 1, na qual Abedrapsas agradece ao deus paterno: <span class=\"greek\">παρεδόθην</span> <span class=\"greek\">εἰς</span> <span class=\"greek\">μάθησιν</span> <span class=\"greek\">τέχνης</span>, «Fui posto como aprendiz para aprender um ofício». AFridrichsen, ConNeot 7, ’42, 6–8; FBeare, NTS 5, ’59, 206–10; UBorse, BZ 12, ’68, 95–103; FDanker, Gingrich Festschr., ’72, 94).<br>\n② Confiar algo para cuidado ou preservação, entregar, recomendar, confiar, com dativo (cf. PFlor 309, 5 <span class=\"greek\">σιωπῇ</span> <span class=\"greek\">παραδ</span>., «Entregar ao esquecimento»; Just., A II, 5, 2 <span class=\"greek\">τὴν</span> … <span class=\"greek\">τῶν</span> <span class=\"greek\">ἀνθρώπων</span> … <span class=\"greek\">πρόνοιαν</span> <span class=\"greek\">ἀγγέλοις</span> … <span class=\"greek\">παρέδωκεν</span>, «[Deus] confiou aos anjos o cuidado dos seres humanos»; Tat. 7, 3 <span class=\"greek\">τῇ</span> <span class=\"greek\">σφῶν</span> <span class=\"greek\">ἀβελτερίᾳ</span> <span class=\"greek\">παρεδόθησαν</span>, «Foram entregues à própria estupidez»): <span class=\"greek\">παραδίδοσθαι</span> <span class=\"greek\">τῇ</span> <span class=\"greek\">χάριτι</span> <span class=\"greek\">τοῦ</span> <span class=\"greek\">κυρίου</span> <span class=\"greek\">ὑπό</span> <span class=\"greek\">τινος</span>, «Ser recomendado por alguém à graça do Senhor», <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.15.40\" target=\"_blank\" rel=\"noopener noreferrer\">Ac 15:40</a>. <span class=\"greek\">Ἀντιόχεια</span>, <span class=\"greek\">ὅθεν</span> <span class=\"greek\">ἦσαν</span> <span class=\"greek\">παραδεδομένοι</span> <span class=\"greek\">τῇ</span> <span class=\"greek\">χάριτι</span> <span class=\"greek\">τοῦ</span> <span class=\"greek\">θεοῦ</span> <span class=\"greek\">εἰς</span> <span class=\"greek\">τὸ</span> <span class=\"greek\">ἔργον</span>, «Antioquia, de onde (haviam partido) recomendados à graça de Deus para a obra», 14:26.—<span class=\"greek\">παρεδίδου</span> <span class=\"greek\">τῷ</span> <span class=\"greek\">κρίνοντι</span>, «Entregava sua causa àquele que julga», <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1PE.2.23\" target=\"_blank\" rel=\"noopener noreferrer\">1 Pt 2:23</a>.<br>\n③ Transmitir a outrem aquilo que se sabe, referente à tradição oral ou escrita, transmitir, passar adiante, relatar, ensinar (Theognis 1, 28f transmite aquilo que ele próprio aprendeu como <span class=\"greek\">παῖς</span>, <span class=\"greek\">ἀπὸ</span> <span class=\"greek\">τῶν</span> <span class=\"greek\">ἀγαθῶν</span>; Pla., Phil. 16c, Ep. 12, 359d <span class=\"greek\">μῦθον</span>; Demosth. 23, 65; Polyb. 7, 1, 1; 10, 28, 3; Diod S 12, 13, 2 <span class=\"greek\">π</span>. <span class=\"greek\">τινί</span> <span class=\"greek\">τι</span>, «Transmitir alguma coisa às gerações futuras», <span class=\"greek\">εἰς</span> <span class=\"greek\">ἅπαντα</span> <span class=\"greek\">τὸν</span> <span class=\"greek\">αἰῶνα</span>; Plut., Nic. 524 [1, 5]; Herm. Wr. 13, 15; Jos., C. Ap. 1, 60 <span class=\"greek\">τὴν</span> <span class=\"greek\">κατὰ</span> <span class=\"greek\">νόμους</span> <span class=\"greek\">παραδεδομένην</span> <span class=\"greek\">εὐσέβειαν</span>; PMagd 33, 5, sobre relatório à polícia acerca dos fatos de um caso; Just.; A I, 54, 1 <span class=\"greek\">τὰ</span> <span class=\"greek\">μυθοποιηθέντα</span>), <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.1.2\" target=\"_blank\" rel=\"noopener noreferrer\">Lk 1:2</a>. <span class=\"greek\">παραδόσεις</span>, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MRK.7.13\" target=\"_blank\" rel=\"noopener noreferrer\">Mk 7:13</a> (sobre a tradição dos fariseus, como Jos., Ant. 13, 297; cf. o termo rabínico <span class=\"hebrew\" dir=\"rtl\">מָסַר</span>); <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1CO.11.2\" target=\"_blank\" rel=\"noopener noreferrer\">1 Cor 11:2</a>. <span class=\"greek\">ἔθη</span>, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.6.14\" target=\"_blank\" rel=\"noopener noreferrer\">Ac 6:14</a>. <span class=\"greek\">ὁ</span> <span class=\"greek\">ἡμῖν</span> <span class=\"greek\">παραδοθεὶς</span> <span class=\"greek\">λόγος</span>, «O ensinamento transmitido a nós», Pol 7:2 (Just., D. 53, 6). <span class=\"greek\">ἡ</span> <span class=\"greek\">παραδοθεῖσα</span> <span class=\"greek\">αὐτοῖς</span> <span class=\"greek\">ἁγία</span> <span class=\"greek\">ἐντολή</span>, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/2PE.2.21\" target=\"_blank\" rel=\"noopener noreferrer\">2 Pt 2:21</a> (ApcMos 23 <span class=\"greek\">τὴν</span> <span class=\"greek\">ἐντολήν</span> <span class=\"greek\">μου</span> <span class=\"greek\">ἣν</span> <span class=\"greek\">παρέδωκά</span> <span class=\"greek\">σοι</span>). <span class=\"greek\">ἡ</span> <span class=\"greek\">παραδοθεῖσα</span> <span class=\"greek\">τοῖς</span> <span class=\"greek\">ἁγίοις</span> <span class=\"greek\">πίστις</span>, Jd 3. <span class=\"greek\">τὰ</span> <span class=\"greek\">παραδοθέντα</span> (Philo, Fuga 200), Dg 11:1. <span class=\"greek\">παρεδίδοσαν</span> <span class=\"greek\">αὐτοῖς</span> <span class=\"greek\">φυλάσσειν</span> <span class=\"greek\">τὰ</span> <span class=\"greek\">δόγματα</span>, «Transmitiam-lhes as determinações para que as observassem», <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.16.4\" target=\"_blank\" rel=\"noopener noreferrer\">Ac 16:4</a>.—(Em contraste com <span class=\"greek\">παραλαμβάνειν</span> [o mesmo contraste em Diod S 1, 91, 4; 3, 65, 6; 5, 2, 3; PHerm 119 III, 22; BGU 1018, 24; PThéad 8, 25]), «Transmitir», <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1CO.11.23\" target=\"_blank\" rel=\"noopener noreferrer\">1 Cor 11:23a</a>; 15:3; AcPlCor 2:4; EpilMosq 2. Com conotação de admiração e mistério (sobre mistérios e cerimônias: Theon Smyrn., Expos. Rer. Math. p. 14 Hiller <span class=\"greek\">τελετὰς</span> <span class=\"greek\">παραδιδόναι</span>; Diod S 5, 48, 4 <span class=\"greek\">μυστηρίων</span> <span class=\"greek\">τελετὴ</span> <span class=\"greek\">παραδοθεῖσα</span>; Strabo 10, 3, 7; Wsd 14:15 <span class=\"greek\">μυστήρια</span> <span class=\"greek\">καὶ</span> <span class=\"greek\">τελετάς</span>. ParJer 9:29 <span class=\"greek\">τὰ</span> <span class=\"greek\">μυστήρια</span> … <span class=\"greek\">τῷ</span> <span class=\"greek\">Βαρούχ</span>; Just., D. 70, 1 <span class=\"greek\">τὰ</span> <span class=\"greek\">τοῦ</span> <span class=\"greek\">Μίθρου</span> <span class=\"greek\">μυστήρια</span> <span class=\"greek\">παραδιδόντες</span>; cf. 78, 6. Cf. Herm. Wr. 13, 1 <span class=\"greek\">παλιγγενεσίαν</span>; PGM 4, 475), <span class=\"greek\">πάντα</span> (<span class=\"greek\">πᾶς</span> 1d<span class=\"greek\">β</span>) <span class=\"greek\">μοι</span> <span class=\"greek\">παρεδόθη</span> <span class=\"greek\">ὑπὸ</span> <span class=\"greek\">τ</span>. <span class=\"greek\">πατρός</span> <span class=\"greek\">μου</span>, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.11.27\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 11:27</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.10.22\" target=\"_blank\" rel=\"noopener noreferrer\">Lk 10:22</a> (cf. Herm. Wr. 1, 32 <span class=\"greek\">πάτερ</span> … <span class=\"greek\">παρέδωκας</span> <span class=\"greek\">αὐτῷ</span> [<span class=\"greek\">ὁ</span> <span class=\"greek\">σὸς</span> <span class=\"greek\">ἄνθρωπος</span> está subentendido] <span class=\"greek\">τὴν</span> <span class=\"greek\">πᾶσαν</span> <span class=\"greek\">ἐξουσίαν</span>; em Vett. Val. 221, 23, a astrologia é <span class=\"greek\">ὑπὸ</span> <span class=\"greek\">θεοῦ</span> <span class=\"greek\">παραδεδομένη</span> <span class=\"greek\">τ</span>. <span class=\"greek\">ἀνθρώποις</span>.—Sobre a bibliografia a respeito deste dito de Jesus, ver <span class=\"greek\">υἱός</span> 2d<span class=\"greek\">β</span>).—Ver <span class=\"greek\">παράδοσις</span>, final.<br>\n④ Tornar possível que algo aconteça, deixar, permitir (Hdt. 5, 67; 7, 18 [sujeito <span class=\"greek\">ὁ</span> <span class=\"greek\">θεός</span>]; X., An. 6, 6, 34 [<span class=\"greek\">οἱ</span> <span class=\"greek\">θεοί</span>]; Isocr. 5, 118 [<span class=\"greek\">οἱ</span> <span class=\"greek\">καιροί</span>]; Polyb. 22, 24, 9 <span class=\"greek\">τῆς</span> <span class=\"greek\">ὥρας</span> <span class=\"greek\">παραδιδούσης</span>): <span class=\"greek\">ὅταν</span> <span class=\"greek\">παραδοῖ</span> <span class=\"greek\">ὁ</span> <span class=\"greek\">καρπός</span>, «Quando a (condição da) colheita permitir», <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MRK.4.29\" target=\"_blank\" rel=\"noopener noreferrer\">Mk 4:29</a>.—Sobre a palavra em geral: WPopkes, Christus Traditus, ’67.—M-M. EDNT. TW. Spicq. Sv.</p></section></article>\n<article class=\"entry-card\" id=\"entry-bdag-0268-19\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">παράδοξος, ον</h1><div class=\"entry-meta\"><span>adjetivo</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução integral</div><p class=\"entry-text\"><span class=\"greek\">παράδοξος</span>, <span class=\"greek\">ον</span> (<span class=\"greek\">παρά</span>, <span class=\"greek\">δόξα</span>; X., Pla. e posteriores; inscrições, papiros, LXX; JosAs 28:1, códice A <span class=\"greek\">π</span>. <span class=\"greek\">θαῦμα</span> [Bat.]; ApcSed 11:1 p. 134, 10 Ja.; EpArist 175; Philo; Jos., C. Ap. 1, 53 e outros; Just.; empréstimo no hebraico rabínico), contrário à opinião comum ou superior às expectativas, estranho, maravilhoso, extraordinário, notável: <span class=\"greek\">κατάστασις</span> <span class=\"greek\">τῆς</span> <span class=\"greek\">πολιτείας</span>, Dg 5:4. <span class=\"greek\">σημεῖον</span>, 1 Cl 25:1. Substantivado no plural, <span class=\"greek\">παράδοξα</span>, «Coisas maravilhosas» (Lucian, Somn. 14; Aelian, VH 13, 33; Celsus 1, 6; Philo, Mos. 1, 212; Jos., Bell. 4, 238), <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.5.26\" target=\"_blank\" rel=\"noopener noreferrer\">Lk 5:26</a>; GJs 19:2; 20:3.—OWeinreich, Antike Heilungswunder 1909, 198f.—DELG s.v. <span class=\"greek\">δοκάω</span>. M-M. TW.</p></section></article>\n<article class=\"entry-card\" id=\"entry-bdag-0268-20\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">παράδοσις, εως, ἡ</h1><div class=\"entry-meta\"><span>substantivo feminino</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução integral</div><p class=\"entry-text\"><span class=\"greek\">παράδοσις</span>, <span class=\"greek\">εως</span>, <span class=\"greek\">ἡ</span> (<span class=\"greek\">παρά</span>, <span class=\"greek\">δίδωμι</span>; Thu. e posteriores; inscrições, papiros, LXX, Philo, Joseph.; Just., D. 38, 2; Tat. 39, 1), «transmissão, entrega».<br>\n① Ato de entregar alguém às autoridades, rendição, prisão (Diod S 11, 33, 4), PEg2, 29.<br>\n② Conteúdo de instrução transmitida, tradição, relativo a ensinamentos, mandamentos, narrativas e outros: inicialmente com sentido ativo (Pla., Leg. 7 p. 803a; Ps.-Pla., Def. 416; Epict. 2, 23, 40; Philo, Ebr. 120; Jos., Vi. 361), mas em nossa literatura apenas no sentido passivo, aquilo que se transmitiu (SIG 704e, 12 <span class=\"greek\">εἰσαγαγὼν</span> <span class=\"greek\">τὴν</span> <span class=\"greek\">τῶν</span> <span class=\"greek\">μυστηρίων</span> <span class=\"greek\">παράδοσιν</span>; Herm. Wr. 13, 22b <span class=\"greek\">τῆς</span> <span class=\"greek\">παλιγγενεσίας</span> <span class=\"greek\">τὴν</span> <span class=\"greek\">παράδοσιν</span>; Tat. 39, 1 <span class=\"greek\">τὴν</span> <span class=\"greek\">τῶν</span> <span class=\"greek\">Ἑλλήνων</span> <span class=\"greek\">παράδοσιν</span>; Orig., C. Cels. 1, 52, 15; Hippol., Ref. 9, 23, 1): sobre a tradição preservada pelos escribas e fariseus (Orig., C. Cels. 2, 1, 46; Hippol., Ref. 9, 28, 4). Eles mesmos a denominavam <span class=\"greek\">ἡ</span> <span class=\"greek\">παράδοσις</span> <span class=\"greek\">τῶν</span> <span class=\"greek\">πρεσβυτέρων</span>, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.15.2\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 15:2</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MRK.7.5\" target=\"_blank\" rel=\"noopener noreferrer\">Mk 7:5</a>; cf. v. 3. Ao conversar com eles, Jesus a chama <span class=\"greek\">ἡ</span> <span class=\"greek\">παράδοσις</span> <span class=\"greek\">ὑμῶν</span>, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.15.3\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 15:3</a>, 6; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MRK.7.9\" target=\"_blank\" rel=\"noopener noreferrer\">Mk 7:9</a>, 13, ou mesmo <span class=\"greek\">ἡ</span> <span class=\"greek\">παράδοσις</span> <span class=\"greek\">τῶν</span> <span class=\"greek\">ἀνθρώπων</span>, v. 8 (sobre a <span class=\"greek\">π</span>. farisaica, ver ABaumgarten, HTR 80, ’87, 63–77). Paulo emprega a última expressão para caracterizar ensino dissidente em Colossos, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/COL.2.8\" target=\"_blank\" rel=\"noopener noreferrer\">Col 2:8</a>. Ao recordar seu passado judaico, apresenta-se como <span class=\"greek\">ζηλωτὴς</span> <span class=\"greek\">τῶν</span> <span class=\"greek\">πατρικῶν</span> <span class=\"greek\">παραδόσεων</span>, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/GAL.1.14\" target=\"_blank\" rel=\"noopener noreferrer\">Gal 1:14</a> (cf. Jos., Ant. 13, 297 <span class=\"greek\">τὰ</span> <span class=\"greek\">ἐκ</span> <span class=\"greek\">παραδόσεως</span> <span class=\"greek\">τῶν</span> <span class=\"greek\">πατέρων</span>; 408. Entende-se aí a tradição dos rabinos [«pais»; ver Pirqe Aboth], aceita pelos fariseus, mas rejeitada pelos saduceus). Sobre ensino cristão, <span class=\"greek\">ὁ</span> <span class=\"greek\">τῆς</span> <span class=\"greek\">π</span>. <span class=\"greek\">ἡμῶν</span> <span class=\"greek\">κανών</span>, 1 Cl 7:2. Sobre o ensino de Paulo, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/2TH.3.6\" target=\"_blank\" rel=\"noopener noreferrer\">2 Th 3:6</a> (empregado com <span class=\"greek\">παραλαμβάνειν</span>; cf. Iren. 3, 3, 3 [Harv. II, 11, 2]). <span class=\"greek\">ἀποστόλων</span> <span class=\"greek\">π</span>., Dg 11:6. No plural, ensinamentos individuais, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1CO.11.2\" target=\"_blank\" rel=\"noopener noreferrer\">1 Cor 11:2</a> (com <span class=\"greek\">παραδιδόναι</span>); <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/2TH.2.15\" target=\"_blank\" rel=\"noopener noreferrer\">2 Th 2:15</a> (ver ASeeberg, D. Katechismus d. Urchristenheit 1903, 1ff; 41f).—WKümmel, Jesus u. d. jüd. Traditionsgedanke: ZNW 33, ’34, 105–30; ADeneffe, D. Traditionsbegriff ’31, 1ff; JRanft, D. Ursprung des kath. Traditionsprinzips ’31; LGoppelt, Tradition nach Paulus, Kerygma u. Dogma 4, ’58, 213–33; BGerhardsson, Memory and Manuscript, etc. ’61 (judaísmo rabínico e cristianismo primitivo); PFannon, The Infl. of Trad. in St. Paul, TU 102, ’68, 292–307.—<span class=\"greek\">ὡς</span> <span class=\"greek\">ἐκ</span> <span class=\"greek\">παραδόσεως</span> <span class=\"greek\">ἀγράφου</span> <span class=\"greek\">εἰς</span> <span class=\"greek\">αὐτὸν</span> <span class=\"greek\">ἥκοντα</span> <span class=\"greek\">παρατέθειται</span>, «Ele transmite (algumas outras) coisas que lhe chegaram aparentemente por tradição não escrita», Papias (2:11); cf. Papias (2:7f; 14).—DELG s.v. <span class=\"greek\">δίδωμι</span> A 1. M-M. EDNT. TW. Sv.</p></section></article>"};
